/* Deutsch mit Liedern – eigene Lieder (Text: Dzianis Prudnikau, Musik: Suno). suno = Song-ID bei Suno. */
(window.DM || (window.DM = {})).songs = [{"id": "a1-01-hallo", "level": "A1", "title": "Hallo, ich bin neu hier", "theme": "Sich vorstellen: Name, Herkunft, Wohnort, Beruf, Sprachen", "grammar": "Präsens (sein, heißen, kommen, wohnen, sprechen), W-Fragen (Wie? Woher? Wo?)", "intro": "Dein erstes Lied auf Deutsch: Hier stellen sich zwei neue Kursteilnehmer vor. Sing mit und stell dich danach selbst vor!", "lyrics": "[Verse 1]\nHallo, hallo! Ich bin neu hier.\nIch heiße Mira – und wer bist du? Sag es mir!\nIch komme aus Syrien, ich wohne in Essen.\nIch lerne Deutsch am Morgen und nach dem Essen.\n\n[Chorus]\nWie heißt du? Woher kommst du?\nWo wohnst du? Ich höre zu.\nWie heißt du? Woher kommst du?\nHallo, hallo – ich und du!\n\n[Verse 2]\nHallo, ich heiße Tarek, ich komme aus Marokko.\nIch wohne in Bochum und ich trinke gern Kakao.\nIch bin Koch von Beruf und ich koche gern.\nIch spreche Arabisch – und Deutsch lerne ich gern.\n\n[Chorus]\nWie heißt du? Woher kommst du?\nWo wohnst du? Ich höre zu.\nWie heißt du? Woher kommst du?\nHallo, hallo – ich und du!\n\n[Bridge]\nFreut mich! – Freut mich auch!\nFreut mich! – Freut mich auch!\nHerzlich willkommen hier im Kurs!\n\n[Outro]\nWie heißt du? Woher kommst du?\nHallo, hallo – ich und du!", "vocab": [["der Name, die Namen", "So heißt eine Person, z. B. Mira oder Tarek."], ["heißen", "„Mein Name ist …“ – das sagt man auch so: „Ich … Mira.“"], ["kommen aus", "sagen, aus welchem Land man ist"], ["wohnen in", "Hier ist meine Wohnung, z. B. in Essen."], ["der Kurs, die Kurse", "Hier lernen viele Menschen zusammen."], ["der Beruf, die Berufe", "die Arbeit, z. B. Lehrerin, Ärztin oder Koch"], ["der Koch, die Köche", "Er macht das Essen im Restaurant."], ["sprechen", "Wörter sagen, z. B. Arabisch oder Deutsch"], ["lernen", "Neues im Kopf speichern, z. B. im Kurs"], ["Freut mich!", "Das sagt man: Schön, dich kennenzulernen."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich komme aus Syrien, ich ___ in Essen.", "Wo wohnst du? Ich ___ zu.", "Ich bin Koch von ___ und ich koche gern.", "Ich ___ Arabisch – und Deutsch lerne ich gern.", "Herzlich willkommen hier im ___!"], "solutions": ["wohne", "höre", "Beruf", "spreche", "Kurs"]}, "suno": "4b7dd70f-7896-4953-a910-821437e1f6d7"}, {"id": "a1-02-wie-spaet", "level": "A1", "title": "Wie spät ist es?", "theme": "Zahlen und Uhrzeit, Tagesablauf", "grammar": "Uhrzeit (Wie spät ist es? Um wie viel Uhr?), Zahlen, Präsens, trennbares Verb aufstehen", "intro": "Eins, zwei, drei – und los! In diesem Reggae-Song lernst du Zahlen und die Uhrzeit. Achte auf „halb“ und „Viertel“!", "lyrics": "[Verse 1]\nEins, zwei, drei – der Tag ist neu.\nVier, fünf, sechs – ich stehe auf um sechs.\nSieben, acht – der Kaffee ist gemacht.\nNeun und zehn – ich muss jetzt gehen.\n\n[Chorus]\nWie spät ist es? Wie spät ist es?\nEs ist acht Uhr – nicht vergessen!\nWie spät ist es? Sag es mir!\nEs ist acht Uhr – der Bus ist hier!\n\n[Verse 2]\nUm halb neun beginnt der Kurs,\num Viertel nach zehn ist Pause – ich habe Durst!\nUm Viertel vor eins ist der Unterricht aus,\ndann fahre ich mit dem Bus nach Haus.\n\n[Chorus]\nWie spät ist es? Wie spät ist es?\nEs ist acht Uhr – nicht vergessen!\nWie spät ist es? Sag es mir!\nEs ist acht Uhr – der Bus ist hier!\n\n[Bridge]\nZehn, zwanzig, dreißig, vierzig, fünfzig –\nsechzig Minuten hat die Stunde. Richtig!\nVierundzwanzig Stunden hat ein Tag.\n\n[Outro]\nWie spät ist es? Es ist zehn nach drei.\nDer Tag ist um – und ich bin frei!", "vocab": [["die Uhr, die Uhren", "Sie zeigt die Zeit."], ["halb neun", "8:30 Uhr"], ["Viertel nach zehn", "10:15 Uhr"], ["Viertel vor eins", "12:45 Uhr"], ["die Pause, die Pausen", "kurze Zeit ohne Arbeit oder Unterricht"], ["beginnen", "anfangen, starten"], ["aufstehen", "morgens aus dem Bett kommen"], ["die Stunde, die Stunden", "60 Minuten"], ["die Minute, die Minuten", "60 Sekunden"], ["der Durst", "Ich möchte etwas trinken."], ["der Unterricht", "die Zeit im Kurs mit der Lehrerin oder dem Lehrer"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Vier, fünf, sechs – ich ___ auf um sechs.", "Um ___ neun beginnt der Kurs,", "um Viertel nach zehn ist ___ – ich habe Durst!", "dann fahre ich mit dem ___ nach Haus.", "Vierundzwanzig ___ hat ein Tag."], "solutions": ["stehe", "halb", "Pause", "Bus", "Stunden"]}, "suno": "65539704-d378-4075-8c7e-001e087b2eb2"}, {"id": "a1-03-familie", "level": "A1", "title": "Das ist meine Familie", "theme": "Familie und Verwandte", "grammar": "Possessivartikel mein/meine/dein/deine, haben + Akkusativ (einen/eine/ein, kein/keine)", "intro": "Wer gehört zu deiner Familie? In diesem Folk-Song stellt eine Frau ihre Familie vor. Danach kannst du deine eigene Familie beschreiben.", "lyrics": "[Verse 1]\nDas ist mein Vater, er kocht sehr gut.\nDas ist meine Mutter, sie hat viel Mut.\nIch habe einen Bruder und eine Schwester,\nmein Bruder heißt Sami, und sie heißt Esther.\n\n[Chorus]\nDas ist meine Familie,\nich liebe sie, ich liebe sie!\nUnd du, und du – wie groß ist deine Familie?\nKomm, erzähl es mir!\n\n[Verse 2]\nMeine Oma ist alt, sie ist achtzig Jahre.\nMein Opa ist lustig, er hat keine Haare.\nMeine Schwester hat ein Baby, so süß und klein.\nIch bin jetzt Tante – das ist so fein!\n\n[Chorus]\nDas ist meine Familie,\nich liebe sie, ich liebe sie!\nUnd du, und du – wie groß ist deine Familie?\nKomm, erzähl es mir!\n\n[Bridge]\nHast du einen Bruder? – Ja, ich habe einen Bruder.\nHast du eine Schwester? – Nein, ich habe keine Schwester.\nHast du ein Kind? – Ja, ich habe ein Kind.\nWir sind eine Familie – so, wie wir sind.\n\n[Outro]\nDas ist meine Familie!", "vocab": [["der Vater, die Väter", "der Papa"], ["die Mutter, die Mütter", "die Mama"], ["der Bruder, die Brüder", "ein Junge oder Mann mit denselben Eltern wie ich"], ["die Schwester, die Schwestern", "ein Mädchen oder eine Frau mit denselben Eltern wie ich"], ["die Oma, die Omas", "die Mutter von Mama oder Papa"], ["der Opa, die Opas", "der Vater von Mama oder Papa"], ["das Baby, die Babys", "ein sehr kleines Kind"], ["die Tante, die Tanten", "die Schwester von Mama oder Papa"], ["die Familie, die Familien", "Eltern, Kinder, Oma, Opa …"], ["der Mut", "keine Angst haben"], ["lustig", "Die Person macht Witze, man lacht viel."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Das ist mein ___, er kocht sehr gut.", "Ich habe ___ Bruder und eine Schwester,", "Meine Oma ist alt, sie ist ___ Jahre.", "Meine Schwester hat ein ___, so süß und klein.", "Hast du eine Schwester? – Nein, ich habe ___ Schwester."], "solutions": ["Vater", "einen", "achtzig", "Baby", "keine"]}, "suno": "39346fc5-7cbb-448c-80e8-d6ba300fbf91"}, {"id": "a1-04-supermarkt", "level": "A1", "title": "Im Supermarkt", "theme": "Essen und Einkaufen, Preise, Bezahlen", "grammar": "Akkusativ (einen/eine/ein), möchten, Fragen nach dem Preis (Was kostet …?)", "intro": "Dein Kühlschrank ist leer? Dann ab in den Supermarkt! Mit diesem Funk-Song übst du Lebensmittel, Preise und Bezahlen.", "lyrics": "[Verse 1]\nIch gehe heute in den Supermarkt,\nich brauche Brot, ich brauche Quark.\nEin Kilo Äpfel und einen Salat,\nund Milch und Eier – dann bin ich satt.\n\n[Chorus]\nWas möchten Sie? – Ich möchte Brot.\nWas kostet das? – Zwei Euro. Gut!\nWas möchten Sie? – Ich nehme Tee.\nDanke schön! – Bitte schön! Tschüss und ade!\n\n[Verse 2]\nIch suche Reis – wo ist der Reis?\nDie Verkäuferin sagt: „Ich weiß, ich weiß!\nDa hinten links, im Regal Nummer drei.“\nIch kaufe noch Tomaten – und dann bin ich frei.\n\n[Chorus]\nWas möchten Sie? – Ich möchte Brot.\nWas kostet das? – Zwei Euro. Gut!\nWas möchten Sie? – Ich nehme Tee.\nDanke schön! – Bitte schön! Tschüss und ade!\n\n[Bridge]\nZahlen Sie bar oder mit Karte?\nMit Karte, bitte – ich warte.\nBrauchen Sie eine Tüte? – Nein, danke schön,\nich habe eine Tasche. Auf Wiedersehen!\n\n[Outro]\nWas möchten Sie? – Ich möchte Brot.\nDanke schön! – Bitte schön!", "vocab": [["der Supermarkt, die Supermärkte", "ein großes Geschäft für Essen und Getränke"], ["das Brot, die Brote", "Man isst es zum Frühstück, mit Butter und Käse."], ["das Kilo, die Kilos", "1000 Gramm"], ["der Apfel, die Äpfel", "rundes Obst, rot oder grün"], ["der Reis", "kleine weiße Körner, man kocht sie in Wasser"], ["das Regal, die Regale", "Hier stehen die Produkte im Geschäft."], ["bar zahlen", "mit Münzen und Scheinen bezahlen"], ["die Tüte, die Tüten", "aus Plastik oder Papier, für den Einkauf"], ["die Verkäuferin, die Verkäuferinnen", "Sie arbeitet im Geschäft und hilft."], ["die Karte, die Karten", "Bankkarte: Man bezahlt ohne Münzen und Scheine."], ["satt", "Ich habe keinen Hunger mehr."], ["das Ei, die Eier", "Das Huhn legt es."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich ___ Brot, ich brauche Quark.", "Ein ___ Äpfel und einen Salat,", "Was ___ das? – Zwei Euro. Gut!", "Da hinten links, im ___ Nummer drei.“", "Zahlen Sie ___ oder mit Karte?"], "solutions": ["brauche", "Kilo", "kostet", "Regal", "bar"]}, "suno": "2f5f7692-f67a-4a0a-bef1-219e4e5191ef"}, {"id": "a1-05-meine-woche", "level": "A1", "title": "Meine Woche", "theme": "Wochentage und Tagesablauf", "grammar": "Trennbare Verben (aufstehen, aufräumen, anrufen, einkaufen, fernsehen, mitkommen, ausschlafen), am + Wochentag", "intro": "Montag, Dienstag, Mittwoch … Was machst du jeden Tag? In diesem Indie-Pop-Song lernst du die Wochentage und trennbare Verben.", "lyrics": "[Verse 1]\nAm Montag stehe ich früh auf,\nam Dienstag räume ich die Küche auf.\nAm Mittwoch rufe ich Mama an,\nam Donnerstag kaufe ich ein – und dann?\n\n[Chorus]\nMontag, Dienstag, Mittwoch, Donnerstag,\nFreitag, Samstag, Sonntag – jeden Tag!\nWas machst du am Montag? Was machst du heute?\nDie Woche ist lang – hallo, liebe Leute!\n\n[Verse 2]\nAm Freitag sehe ich am Abend fern,\nich esse Pizza – Pizza esse ich gern.\nAm Samstag gehe ich tanzen, mein Freund kommt mit,\nwir tanzen zusammen, Schritt für Schritt.\n\n[Chorus]\nMontag, Dienstag, Mittwoch, Donnerstag,\nFreitag, Samstag, Sonntag – jeden Tag!\nWas machst du am Montag? Was machst du heute?\nDie Woche ist lang – hallo, liebe Leute!\n\n[Bridge]\nUnd am Sonntag? Am Sonntag?\nAm Sonntag schlafe ich lange aus,\nich bleibe gern zu Haus.\nIch bleibe gern zu Haus!\n\n[Outro]\nMontag, Dienstag, Mittwoch … und du?\nWas machst du am Sonntag? Und du?", "vocab": [["aufstehen", "morgens aus dem Bett kommen"], ["aufräumen", "Ordnung machen, alles an seinen Platz legen"], ["anrufen", "mit dem Handy oder Telefon eine Person kontaktieren"], ["einkaufen", "in den Supermarkt gehen und Essen holen"], ["fernsehen", "einen Film oder Nachrichten im TV anschauen"], ["mitkommen", "zusammen mit einer Person gehen"], ["ausschlafen", "morgens sehr lange im Bett bleiben, ohne Wecker"], ["die Woche, die Wochen", "sieben Tage"], ["der Abend, die Abende", "die Zeit nach der Arbeit, ungefähr 18 bis 22 Uhr"], ["zu Hause", "in meiner Wohnung"], ["tanzen", "sich zur Musik bewegen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Am Montag stehe ich ___ auf,", "Am Mittwoch ___ ich Mama an,", "Am Freitag sehe ich am Abend ___,", "ich esse Pizza – Pizza esse ich ___.", "Am Sonntag schlafe ich lange ___,"], "solutions": ["früh", "rufe", "fern", "gern", "aus"]}, "suno": "1c673ea8-5bca-4174-94e2-79b77a8987c1"}, {"id": "a1-06-was-ziehst-du-an", "level": "A1", "title": "Was ziehst du an?", "theme": "Kleidung, Farben und Wetter", "grammar": "Verben mit Vokalwechsel (tragen – du trägst – er trägt, nehmen – er nimmt), Akkusativ (einen/eine/ein)", "intro": "Regen, Sonne, Schnee – was ziehst du heute an? Mit diesem Lied lernst du Kleidung und Farben und übst Verben wie tragen und nehmen.", "lyrics": "[Verse 1]\nEs ist Montag, es ist kalt, der Himmel ist grau.\nIch nehme meinen Mantel, er ist dunkelblau.\nDu trägst eine Mütze, sie ist rot und warm.\nIch nehme meinen Schal und dich in den Arm.\n\n[Chorus]\nWas ziehst du an? Was ziehst du an?\nEine Jacke, eine Hose – dann geht es los!\nWas trägst du heute? Sag es mir:\nRot, gelb, grün und blau – ich warte hier.\n\n[Verse 2]\nEs ist Sommer, die Sonne scheint so hell.\nSie trägt ein Kleid, ein weißes Kleid – und sie ist schnell.\nEr trägt eine Sonnenbrille und ein T-Shirt, orange.\nWir tragen keine Socken – wir laufen am Strand.\n\n[Chorus]\nWas ziehst du an? Was ziehst du an?\nEine Jacke, eine Hose – dann geht es los!\nWas trägst du heute? Sag es mir:\nRot, gelb, grün und blau – ich warte hier.\n\n[Bridge]\nEs regnet – nimm einen Schirm!\nEs schneit – nimm deine Handschuhe!\nDie Sonne scheint – nimm deine Brille!\nUnd du? Was nimmst du?\n\n[Chorus]\nWas ziehst du an? Was ziehst du an?\nEine Jacke, eine Hose – dann geht es los!\nWas trägst du heute? Sag es mir:\nRot, gelb, grün und blau – ich warte hier.", "vocab": [["anziehen", "Kleidung auf den Körper nehmen: Ich ziehe eine Jacke an."], ["tragen (er trägt)", "Kleidung am Körper haben: Sie trägt ein Kleid."], ["der Mantel, die Mäntel", "eine lange, warme Jacke für den Winter"], ["die Mütze, die Mützen", "Sie ist auf dem Kopf und hält warm."], ["der Schal, die Schals", "Er ist um den Hals."], ["das Kleid, die Kleider", "Kleidung für Frauen und Mädchen, ein Teil"], ["die Hose, die Hosen", "Kleidung für die Beine"], ["die Socke, die Socken", "Sie sind an den Füßen, im Schuh."], ["der Handschuh, die Handschuhe", "Er ist an der Hand und hält warm."], ["der Schirm, die Schirme", "Er hilft gegen Regen."], ["die Farbe, die Farben", "rot, gelb, grün, blau, weiß …"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich nehme meinen ___, er ist dunkelblau.", "Du trägst eine Mütze, sie ist ___ und warm.", "Sie trägt ein Kleid, ein ___ Kleid – und sie ist schnell.", "Es regnet – nimm einen ___!", "Es schneit – nimm deine ___!"], "solutions": ["Mantel", "rot", "weißes", "Schirm", "Handschuhe"]}, "suno": "0f07ffdb-0a97-4ece-aa73-2c75dd32df2e"}, {"id": "a1-07-kopf-und-herz", "level": "A1", "title": "Kopf, Bauch und Herz", "theme": "Der Körper und Bewegung", "grammar": "Imperativ mit du und ihr (Heb die Hände! Hebt die Hände!), Körperteile mit Artikel und Plural", "intro": "Steh auf und mach mit! In diesem Lied bewegst du deinen Körper und lernst die Körperteile. Dabei übst du den Imperativ: Heb die Hände! Tanzt mit!", "lyrics": "[Verse 1]\nSteh auf, steh auf, der Tag ist da!\nHeb die Hände – eins, zwei, ja!\nDreh den Kopf nach links und rechts,\nbeweg die Schultern – gar nicht schlecht!\n\n[Chorus]\nKopf, Bauch und Herz,\nArme, Beine – hoch und runter!\nKopf, Bauch und Herz,\ntanzt mit mir – das Leben ist bunter!\n\n[Verse 2]\nHebt die Arme, alle zusammen,\nklatscht in die Hände, wir fangen an!\nStampft mit den Füßen auf den Boden,\nschaut nach unten, schaut nach oben!\n\n[Chorus]\nKopf, Bauch und Herz,\nArme, Beine – hoch und runter!\nKopf, Bauch und Herz,\ntanzt mit mir – das Leben ist bunter!\n\n[Bridge]\nMach die Augen zu – und atme ein.\nMach die Augen auf – du bist nicht allein.\nLeg die Hand auf dein Herz – hörst du es?\nBumm, bumm, bumm – vergiss das nicht!\n\n[Chorus]\nKopf, Bauch und Herz,\nArme, Beine – hoch und runter!\nKopf, Bauch und Herz,\ntanzt mit mir – das Leben ist bunter!", "vocab": [["der Kopf, die Köpfe", "Hier sind die Augen, die Nase und der Mund."], ["der Bauch, die Bäuche", "Er ist in der Mitte vom Körper. Nach dem Essen ist er voll."], ["das Herz, die Herzen", "Es schlägt in der Brust: bumm, bumm."], ["die Hand, die Hände", "Damit schreibe ich und klatsche."], ["der Arm, die Arme", "Er ist zwischen Schulter und Hand."], ["das Bein, die Beine", "Damit gehe und laufe ich."], ["der Fuß, die Füße", "Er ist unten am Bein, im Schuh."], ["die Schulter, die Schultern", "Sie ist oben zwischen Hals und Arm."], ["das Auge, die Augen", "Damit sehe ich."], ["heben", "nach oben bewegen: Heb die Hände!"], ["klatschen", "die Hände schnell zusammen schlagen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Heb die ___ – eins, zwei, ja!", "Dreh den ___ nach links und rechts,", "Stampft mit den ___ auf den Boden,", "Mach die ___ zu – und atme ein.", "Leg die Hand auf dein ___ – hörst du es?"], "solutions": ["Hände", "Kopf", "Füßen", "Augen", "Herz"]}, "suno": "217a3994-df38-4360-93fe-ce8e20a8f7ac"}, {"id": "a1-08-ich-kann-das", "level": "A1", "title": "Ich kann das!", "theme": "Hobbys und Fähigkeiten", "grammar": "Modalverben können und wollen mit Satzklammer (Ich kann gut kochen. Willst du mitspielen?)", "intro": "Was kannst du gut? Was willst du lernen? Dieses Mutmach-Lied stellt Hobbys vor und übt die Modalverben können und wollen.", "lyrics": "[Verse 1]\nIch kann gut kochen, ich kann schnell laufen,\nich kann auf dem Markt billig Obst kaufen.\nMeine Schwester kann sehr gut singen,\nmein Bruder kann hoch in den Himmel springen.\n\n[Chorus]\nIch kann das! Ich kann das!\nUnd was ich nicht kann – das lerne ich, Schritt für Schritt.\nIch kann das! Du kannst das!\nKomm, wir können es zusammen – mach mit!\n\n[Verse 2]\nKannst du schwimmen? – Nein, noch nicht,\naber ich will es lernen, im Sommer, ganz sicher!\nWillst du Fußball spielen? – Ja, sehr gern!\nWir spielen im Park – der ist nicht fern.\n\n[Chorus]\nIch kann das! Ich kann das!\nUnd was ich nicht kann – das lerne ich, Schritt für Schritt.\nIch kann das! Du kannst das!\nKomm, wir können es zusammen – mach mit!\n\n[Bridge]\nIch will Deutsch sprechen – jeden Tag ein Wort.\nIch will Gitarre spielen – hier und dort.\nIch kann noch nicht alles – das ist okay.\nMorgen kann ich mehr – ole, ole!\n\n[Chorus]\nIch kann das! Ich kann das!\nUnd was ich nicht kann – das lerne ich, Schritt für Schritt.\nIch kann das! Du kannst das!\nKomm, wir können es zusammen – mach mit!", "vocab": [["können", "Ich kann schwimmen = Ich habe es gelernt, es geht."], ["wollen", "Ich will schwimmen = Ich möchte es sehr, das ist mein Plan."], ["kochen", "Essen warm machen, z. B. Suppe"], ["laufen", "schnell gehen, rennen"], ["singen", "Musik mit der Stimme machen"], ["springen", "mit beiden Beinen nach oben gehen"], ["schwimmen", "sich im Wasser bewegen"], ["Fußball spielen", "ein Ballspiel mit zwei Mannschaften"], ["der Park, die Parks", "Grün in der Stadt: Wiese, Bäume, Wege"], ["die Gitarre, die Gitarren", "ein Musikinstrument mit sechs Saiten"], ["Schritt für Schritt", "langsam, ein Teil nach dem anderen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich kann gut kochen, ich kann schnell ___,", "Meine Schwester kann sehr gut ___,", "Kannst du schwimmen? – Nein, noch ___,", "Willst du ___ spielen? – Ja, sehr gern!", "Ich will ___ spielen – hier und dort."], "solutions": ["laufen", "singen", "nicht", "Fußball", "Gitarre"]}, "suno": "5a31ebb4-d8c5-4698-ade6-a374b3aa67a7"}, {"id": "a1-09-ist-es-noch-weit", "level": "A1", "title": "Ist es noch weit?", "theme": "In der Stadt: nach dem Weg fragen, Orte und Wege (geradeaus, links, rechts)", "grammar": "Ja-/Nein-Fragen mit dem Verb auf Position 1 (Ist es noch weit? Fährt hier ein Bus?) und Antworten mit ja, nein und nicht", "intro": "Nachts allein in einer neuen Stadt – wo ist nur die Gartenstraße? Mit diesem Lied fragst du nach dem Weg und übst Ja-/Nein-Fragen und Antworten mit nicht.", "lyrics": "[Verse 1]\nEs ist Nacht, die Stadt ist still,\nich bin neu hier, ich weiß nicht viel.\nDer Regen fällt, die Lichter sind an,\nich steige aus und frage einen Mann:\n„Entschuldigung, ist das die Gartenstraße?“\n„Nein, das ist sie nicht. Gehen Sie geradeaus,\ndann links, dann rechts – dann sind Sie zu Hause.“\n\n[Chorus]\nIst es noch weit? – Nein, nicht weit.\nIst es schon spät? – Ja, es ist spät.\nSiehst du das Licht? – Ja, ich sehe das Licht.\nIst es noch weit? – Nein, nicht weit, nicht weit.\n\n[Verse 2]\nDa ist ein Kiosk, da ist ein Park,\nder Park ist dunkel, der Wind ist stark.\n„Fährt hier ein Bus?“ – „Nein, nicht mehr.\nDie Straße ist leer, der Platz ist leer.“\n„Ist das ein Problem?“ – „Nein, gar nicht.\nSie gehen zehn Minuten – dann sehen Sie ein Licht.“\nIch gehe allein, Schritt für Schritt,\ndie Nacht ist kalt, der Mond geht mit.\n\n[Chorus]\nIst es noch weit? – Nein, nicht weit.\nIst es schon spät? – Ja, es ist spät.\nSiehst du das Licht? – Ja, ich sehe das Licht.\nIst es noch weit? – Nein, nicht weit, nicht weit.\n\n[Bridge]\nIch bin nicht müde, ich bin nicht allein,\ndie Stadt ist groß, mein Weg ist klein.\nEin Fenster ist hell, die Bahn fährt vorbei –\nGartenstraße, Nummer drei.\n\n[Chorus]\nIst es noch weit? – Nein, nicht weit.\nIst es schon spät? – Ja, es ist spät.\nSiehst du das Licht? – Ja, ich sehe das Licht.\nIst es noch weit? – Nein, nicht weit, nicht weit.\n\n[Outro]\nIst das mein Haus? – Ja, das ist dein Haus.\nIst es noch weit? – Nein. Nicht mehr weit.", "vocab": [["die Stadt, die Städte", "Ort mit vielen Häusern und Menschen"], ["die Nacht, die Nächte", "Zeit, wenn es dunkel ist und man schläft"], ["der Regen", "Wasser fällt vom Himmel"], ["das Licht, die Lichter", "Es macht hell, z. B. eine Lampe."], ["aussteigen", "aus dem Bus oder aus der Bahn gehen"], ["die Straße, die Straßen", "Hier fahren Autos, hier gehen Menschen."], ["geradeaus", "nicht links, nicht rechts"], ["weit", "nicht nah – man geht lange"], ["der Kiosk, die Kioske", "kleiner Laden für Getränke, Zeitungen und Snacks"], ["das Fenster, die Fenster", "Durch das Fenster sieht man nach draußen."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich bin neu hier, ich weiß nicht ___.", "Der Regen fällt, die ___ sind an,", "„Nein, das ist sie nicht. Gehen Sie ___,", "der Park ist dunkel, der ___ ist stark.", "Gartenstraße, ___ drei."], "solutions": ["viel", "Lichter", "geradeaus", "Wind", "Nummer"]}, "suno": "bd4a8490-cdbf-44cc-ab45-ecc91ba6a274"}, {"id": "a1-10-ich-rufe-dich-an", "level": "A1", "title": "Ich rufe dich an", "theme": "Familie in der Ferne: telefonieren, Videoanruf, Heimweh", "grammar": "Personalpronomen im Akkusativ (mich, dich, ihn, sie, es, uns, euch: Hörst du mich? Ich sehe dich.)", "intro": "Deine Familie ist weit weg, aber am Telefon ist sie ganz nah. Mit diesem Lied übst du die Pronomen mich, dich, ihn, sie, uns und euch.", "lyrics": "[Verse 1]\nEs ist elf Uhr, die Stadt schläft schon,\nich sitze am Fenster mit meinem Telefon.\nDraußen fährt die letzte Bahn,\nich denke an dich und rufe dich an.\nDu bist so weit, in einem anderen Land,\nich habe dein Foto in meiner Hand.\n\n[Chorus]\nHörst du mich? Ich höre dich.\nSiehst du mich? Ich sehe dich.\nIch rufe dich an, ich rufe dich an –\ndie Nacht ist lang, ich rufe dich an.\n\n[Verse 2]\nDa bist du, Mama, du lachst und winkst,\nmein Bruder ist auch da, er singt.\nIch sehe dich, ich sehe ihn,\nund Papa fragt: „Wie ist Berlin?“\n„Besuchst du uns?“, fragt er leise.\n„Ja, ich besuche euch. Ich plane die Reise.“\n\n[Chorus]\nHörst du mich? Ich höre dich.\nSiehst du mich? Ich sehe dich.\nIch rufe dich an, ich rufe dich an –\ndie Nacht ist lang, ich rufe dich an.\n\n[Bridge]\nDas Bild ist weg, das Netz ist schwach,\nich warte im Dunkeln, ich bin noch wach.\n„Hallo? Hallo? Verstehst du mich?“\n„Ja, wir verstehen dich. Wir lieben dich.“\n\n[Chorus]\nHörst du mich? Ich höre dich.\nSiehst du mich? Ich sehe dich.\nIch rufe dich an, ich rufe dich an –\ndie Nacht ist lang, ich rufe dich an.\n\n[Outro]\n„Gute Nacht“, sage ich, „schlaft gut“ –\nmorgen rufe ich euch wieder an.", "vocab": [["anrufen", "mit dem Telefon sprechen: Ich rufe dich an."], ["das Telefon, die Telefone", "Damit spricht man mit anderen Menschen, hier: das Handy."], ["das Fenster, die Fenster", "Durch das Fenster sieht man nach draußen."], ["das Land, die Länder", "z. B. Deutschland, Syrien, die Ukraine"], ["das Foto, die Fotos", "ein Bild von der Kamera oder vom Handy"], ["winken", "die Hand bewegen und „Hallo!“ oder „Tschüss!“ sagen"], ["besuchen", "zu einer Person fahren und dort Zeit haben"], ["die Reise, die Reisen", "Man fährt in eine andere Stadt oder in ein anderes Land."], ["das Netz", "die Verbindung für Handy und Internet"], ["wach", "nicht schlafen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich sitze am ___ mit meinem Telefon.", "ich denke an dich und rufe dich ___.", "ich habe dein ___ in meiner Hand.", "Ich sehe dich, ich sehe ___,", "Das Bild ist weg, das ___ ist schwach,"], "solutions": ["Fenster", "an", "Foto", "ihn", "Netz"]}, "suno": "812b9309-bfb3-47b7-8db1-b563e24714c1"}, {"id": "a2-01-neue-wohnung", "level": "A2", "title": "Meine neue Wohnung", "theme": "Wohnung, Umzug, Möbel, Nachbarn", "grammar": "Wechselpräpositionen: Wohin? + Akkusativ (stellen, legen, hängen) / Wo? + Dativ (stehen, liegen, hängen); Perfekt", "intro": "Endlich eine eigene Wohnung! Aber wohin mit dem Sofa? In diesem Schlager-Pop-Song übst du Wo? und Wohin? mit Möbeln.", "lyrics": "[Verse 1]\nIch bin umgezogen, das war viel Arbeit,\njetzt wohne ich in Gelsenkirchen – endlich ist es so weit!\nZwei Zimmer, Küche, Bad und ein kleiner Balkon,\ndie Kisten sind noch da, aber ich wohne hier schon.\n\n[Chorus]\nWohin? Wohin? – Ich stelle das Sofa an die Wand.\nWo? Wo? – Das Sofa steht an der Wand.\nWohin? Wohin? – Ich hänge das Bild über das Bett.\nWo? Wo? – Es hängt über dem Bett. Wie nett!\n\n[Verse 2]\nIch habe den Tisch in die Küche gestellt,\ndie Lampe hängt im Flur – sie war billig, für wenig Geld.\nDen Teppich habe ich ins Wohnzimmer gelegt,\ndie Pflanze steht am Fenster, ich habe sie gut gepflegt.\n\n[Chorus]\nWohin? Wohin? – Ich stelle das Sofa an die Wand.\nWo? Wo? – Das Sofa steht an der Wand.\nWohin? Wohin? – Ich hänge das Bild über das Bett.\nWo? Wo? – Es hängt über dem Bett. Wie nett!\n\n[Bridge]\nDie Nachbarin hat geklingelt und Kuchen mitgebracht,\nwir haben Kaffee getrunken und zusammen gelacht.\nJetzt liege ich auf dem Sofa – mein neues Zuhause, gute Nacht!\n\n[Outro]\nWo wohne ich? Hier wohne ich.\nWillkommen bei mir!", "vocab": [["umziehen (ist umgezogen)", "in eine neue Wohnung gehen und dort wohnen"], ["die Miete, die Mieten", "Geld für die Wohnung, jeden Monat"], ["der Balkon, die Balkone", "kleiner Platz draußen an der Wohnung"], ["die Kiste, die Kisten", "großer Karton für Sachen beim Umzug"], ["stellen (wohin?)", "etwas aufrecht an einen Ort bringen, z. B. einen Tisch"], ["legen (wohin?)", "etwas flach an einen Ort bringen, z. B. ein Buch"], ["der Flur, die Flure", "Raum hinter der Wohnungstür, von dort geht man in die Zimmer"], ["der Teppich, die Teppiche", "Er liegt auf dem Boden, weich und warm."], ["die Nachbarin, die Nachbarinnen", "Frau, die neben mir wohnt"], ["das Zuhause", "der Ort, wo ich wohne und mich wohlfühle"], ["klingeln", "an der Tür auf den Knopf drücken"], ["pflegen", "gut für etwas sorgen, z. B. Wasser für Blumen geben"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["die ___ sind noch da, aber ich wohne hier schon.", "Ich habe den Tisch in die Küche ___,", "Den ___ habe ich ins Wohnzimmer gelegt,", "Die Nachbarin hat ___ und Kuchen mitgebracht,", "wir haben Kaffee ___ und zusammen gelacht."], "solutions": ["Kisten", "gestellt", "Teppich", "geklingelt", "getrunken"]}, "suno": "ea390cc6-e053-464f-9a95-f1cd0ded87e5"}, {"id": "a2-02-beim-arzt", "level": "A2", "title": "Gute Besserung", "theme": "Beim Arzt: Krankheiten, Körper, Medikamente, Krankmeldung", "grammar": "Modalverben müssen, dürfen, sollen; weh tun; weil-Sätze", "intro": "Kopfschmerzen, Fieber, Husten – was jetzt? In dieser Akustik-Ballade gehst du zur Ärztin und lernst, was du musst, darfst und sollst.", "lyrics": "[Verse 1]\nMein Kopf tut weh, mein Hals tut weh,\nich habe Fieber – oje, oje!\nIch rufe in der Praxis an – ich muss heute hin,\nweil ich so krank und so müde bin.\n\n[Verse 2]\n„Was fehlt Ihnen denn?“, fragt die Ärztin mich.\n„Ich huste in der Nacht, ich schlafe schlecht – ich kann nicht mehr, ehrlich!“\n„Machen Sie bitte den Mund auf und sagen Sie ‚Aaah‘!\nSie haben eine Erkältung, das ist ganz klar.“\n\n[Chorus]\nSie müssen viel trinken, Sie dürfen nicht rauchen,\nSie sollen im Bett bleiben – Ruhe ist, was Sie jetzt brauchen.\nGute Besserung! Gute Besserung!\nBleiben Sie zu Hause und werden Sie schnell gesund!\n\n[Verse 3]\nIch bekomme ein Rezept und eine Krankmeldung,\nfür meinen Chef – und alles ist in Ordnung.\nIn der Apotheke hole ich Tabletten und Tee,\nich nehme sie dreimal am Tag – bald tut nichts mehr weh.\n\n[Bridge]\nDarf ich arbeiten? – Nein, das dürfen Sie nicht.\nMuss ich wiederkommen? – Ja, am Freitag, das ist Pflicht.\nDarf ich Sport machen? – Nein, noch nicht!\n\n[Outro]\nGute Besserung – und bis bald!", "vocab": [["wehtun (Der Kopf tut weh.)", "Schmerzen machen, z. B. im Kopf oder im Bauch"], ["das Fieber", "Die Körpertemperatur ist hoch, z. B. 39 Grad."], ["die Erkältung, die Erkältungen", "leichte Krankheit mit Schnupfen, Husten und Halsschmerzen"], ["die Praxis, die Praxen", "Hier arbeitet die Ärztin, dort wartet man auf den Termin."], ["das Rezept, die Rezepte", "Papier vom Arzt für Medikamente"], ["die Krankmeldung, die Krankmeldungen", "Papier vom Arzt für den Chef: Ich kann nicht arbeiten."], ["die Apotheke, die Apotheken", "Geschäft für Medikamente"], ["die Tablette, die Tabletten", "kleines Medikament zum Schlucken"], ["Gute Besserung!", "Das sagt man zu kranken Menschen: Werde schnell gesund!"], ["die Ruhe", "keine Arbeit, kein Stress, kein Lärm"], ["Was fehlt Ihnen?", "Frage beim Arzt: Welches Problem haben Sie?"], ["die Pflicht, die Pflichten", "Das muss man machen."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Mein Kopf tut weh, mein ___ tut weh,", "ich habe ___ – oje, oje!", "Sie müssen viel trinken, Sie ___ nicht rauchen,", "Ich bekomme ein ___ und eine Krankmeldung,", "ich nehme sie ___ am Tag – bald tut nichts mehr weh."], "solutions": ["Hals", "Fieber", "dürfen", "Rezept", "dreimal"]}, "suno": "d899bdd0-7cb7-422b-b2c7-bc1251011787"}, {"id": "a2-03-jahreszeiten", "level": "A2", "title": "Jede Jahreszeit", "theme": "Wetter und Jahreszeiten", "grammar": "Nebensätze mit weil und dass; im + Jahreszeit/Monat; Perfekt", "intro": "Sonne, Regen, Wind und Schnee: Dieser Folk-Song wandert durch das Jahr. Du übst Wetterwörter und Sätze mit „weil“ und „dass“.", "lyrics": "[Verse 1]\nIm Frühling ist es mild, die Sonne kommt zurück,\nich gehe gern spazieren, weil die Blumen blühen – so ein Glück!\nIm Sommer ist es heiß, das Thermometer zeigt dreißig Grad,\nich fahre an den See mit meinem Fahrrad.\n\n[Chorus]\nIch mag jede Jahreszeit, weil jede anders ist.\nIch weiß, dass du die Sonne im Winter oft vermisst.\nRegen, Wind und Schnee – egal, ich gehe raus,\nund abends trinke ich Tee zu Haus.\n\n[Verse 2]\nIm Herbst ist es windig, die Blätter werden bunt,\nes regnet oft – doch ich gehe raus, denn das ist gesund.\nIm Winter ist es kalt, manchmal schneit es im Dezember,\num fünf Uhr ist es dunkel – schon seit Anfang November.\n\n[Chorus]\nIch mag jede Jahreszeit, weil jede anders ist.\nIch weiß, dass du die Sonne im Winter oft vermisst.\nRegen, Wind und Schnee – egal, ich gehe raus,\nund abends trinke ich Tee zu Haus.\n\n[Bridge]\nUnd gestern? Gestern hat es den ganzen Tag geregnet.\nIch bin im Treppenhaus nur meinem Nachbarn begegnet.\nWir haben gelacht und gesagt: „Na und?\nMorgen scheint die Sonne wieder – bleib gesund!“", "vocab": [["die Jahreszeit, die Jahreszeiten", "Frühling, Sommer, Herbst oder Winter"], ["mild", "nicht zu kalt und nicht zu warm"], ["blühen", "Die Blumen öffnen sich und haben Farben."], ["das Thermometer, die Thermometer", "Es zeigt die Temperatur."], ["das Blatt, die Blätter", "Es ist grün am Baum und fällt im Herbst."], ["windig", "Die Luft bewegt sich stark."], ["schneien", "Weiße, kalte Flocken fallen vom Himmel."], ["vermissen", "traurig sein, weil etwas oder jemand nicht da ist"], ["begegnen (+ Dativ)", "eine Person zufällig treffen"], ["dunkel", "ohne Licht"], ["das Treppenhaus, die Treppenhäuser", "Dort sind die Treppen in einem Wohnhaus."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich gehe gern spazieren, weil die Blumen ___ – so ein Glück!", "ich fahre an den ___ mit meinem Fahrrad.", "Ich weiß, dass du die Sonne im Winter oft ___.", "Im Herbst ist es ___, die Blätter werden bunt,", "um fünf Uhr ist es ___ – schon seit Anfang November."], "solutions": ["blühen", "See", "vermisst", "windig", "dunkel"]}, "suno": "738c1f98-da42-49e1-acc8-0850e495b2a5"}, {"id": "a2-04-wir-feiern", "level": "A2", "title": "Heute feiern wir", "theme": "Feste und Feiern: Geburtstag, Weihnachten, Zuckerfest, Geschenke", "grammar": "Dativ: Verben mit zwei Objekten (schenken, geben, bringen) und Personalpronomen im Dativ (mir, dir, ihm, ihr, uns, ihnen); gratulieren + Dativ", "intro": "Geburtstag, Weihnachten, Zuckerfest – wir feiern zusammen! Mit diesem Funk-Song übst du, wem du was schenkst.", "lyrics": "[Verse 1]\nHeute ist ein Fest, wir feiern bis zur Nacht,\nich habe meiner Freundin einen Kuchen gemacht.\nIch schenke ihr Blumen und ich singe ihr ein Lied,\nund alle unsere Freunde singen laut mit.\n\n[Chorus]\nAlles Gute! Alles Gute!\nHerzlichen Glückwunsch – heute feiern wir!\nWir gratulieren dir, wir danken dir,\nwir sind so froh – du bist hier!\n\n[Verse 2]\nIm Dezember feiern viele Menschen Weihnachten,\nwir schenken unseren Eltern warme Socken – und alle lachen.\nMein Nachbar feiert mit seiner Familie das Zuckerfest,\ner bringt uns Süßigkeiten – so ein schönes Fest!\n\n[Chorus]\nAlles Gute! Alles Gute!\nHerzlichen Glückwunsch – heute feiern wir!\nWir gratulieren dir, wir danken dir,\nwir sind so froh – du bist hier!\n\n[Bridge]\nWas schenkst du deiner Mutter? – Ich schenke ihr Blumen.\nWas schenkst du deinem Bruder? – Ich schenke ihm ein Spiel.\nWas schenkst du deinen Kindern? – Ich schenke ihnen Zeit,\ndenn Zeit zusammen ist das Schönste – weit und breit.\n\n[Chorus]\nAlles Gute! Alles Gute!\nHerzlichen Glückwunsch – heute feiern wir!\nWir gratulieren dir, wir danken dir,\nwir sind so froh – du bist hier!\n\n[Outro]\nHerzlichen Glückwunsch – wir feiern mit dir!", "vocab": [["feiern", "eine Party machen, einen besonderen Tag zusammen erleben"], ["das Fest, die Feste", "großer Tag mit Essen, Musik und Gästen"], ["schenken (jemandem etwas)", "jemandem etwas geben, ohne Geld dafür zu nehmen"], ["gratulieren (+ Dativ)", "Glück wünschen, z. B. zum Geburtstag"], ["Herzlichen Glückwunsch!", "Das sagt man am Geburtstag oder zur Hochzeit."], ["Weihnachten", "christliches Fest vom 24. bis 26. Dezember"], ["das Zuckerfest", "Fest am Ende vom Ramadan"], ["die Süßigkeit, die Süßigkeiten", "Schokolade, Bonbons, Kekse"], ["die Socke, die Socken", "Man trägt sie an den Füßen, im Schuh."], ["das Geschenk, die Geschenke", "Man bekommt es zum Geburtstag, oft in buntem Papier."], ["weit und breit", "überall, im ganzen Umkreis"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich habe meiner Freundin einen ___ gemacht.", "Ich schenke ihr ___ und ich singe ihr ein Lied,", "Herzlichen Glückwunsch – heute ___ wir!", "Wir ___ dir, wir danken dir,", "er bringt uns ___ – so ein schönes Fest!"], "solutions": ["Kuchen", "Blumen", "feiern", "gratulieren", "Süßigkeiten"]}, "suno": "07b5f491-6d96-44b2-b963-7ba44454bfab"}, {"id": "a2-05-gleis-sieben", "level": "A2", "title": "Gleis sieben", "theme": "Reise und Bahnhof: Tickets, Verspätung, Umsteigen, Ankommen", "grammar": "Perfekt mit haben und sein (Bewegungsverben), Präpositionen mit, nach, zu, in, um", "intro": "Mit dem Zug nach Hamburg – und natürlich gibt es Verspätung! In diesem entspannten Hip-Hop-Song erzählst du im Perfekt von einer Reise.", "lyrics": "[Verse 1]\nIch bin heute früh zum Bahnhof gegangen,\ndie Reise nach Hamburg hat um acht angefangen.\nIch habe mein Ticket online gebucht,\ndann habe ich lange das Gleis gesucht.\n\n[Chorus]\nGleis sieben, Gleis sieben – wo ist mein Zug?\nZehn Minuten Verspätung – ich habe Zeit genug.\nIch warte, ich warte, ich trinke Kaffee,\ndann kommt der ICE – ich steige ein, juchhe!\n\n[Verse 2]\nIn Münster musste ich leider umsteigen,\nder Anschluss war weg – ich konnte nur schweigen.\nDie Zugbegleiterin hat gesagt: „Es tut mir leid,\nder nächste Zug fährt in einer Stunde – Sie haben noch Zeit.“\n\n[Chorus]\nGleis sieben, Gleis sieben – wo ist mein Zug?\nZehn Minuten Verspätung – ich habe Zeit genug.\nIch warte, ich warte, ich trinke Kaffee,\ndann kommt der ICE – ich steige ein, juchhe!\n\n[Verse 3]\nUm drei Uhr bin ich endlich in Hamburg angekommen,\nmeine Tante hat mich am Bahnhof in den Arm genommen.\nWir sind mit der U-Bahn zu ihr gefahren,\nwie früher, wie vor vielen Jahren.\n\n[Bridge]\nEinfach oder hin und zurück?\nZweite Klasse, Fensterplatz – mit ein bisschen Glück.\nGute Reise! Gute Fahrt!\n\n[Outro]\nGleis sieben, Gleis sieben –\nich bin da.", "vocab": [["der Bahnhof, die Bahnhöfe", "Hier fahren Züge ab und kommen an."], ["das Gleis, die Gleise", "Hier hält der Zug; es hat eine Nummer."], ["buchen", "ein Ticket oder ein Hotel reservieren und bezahlen"], ["die Verspätung, die Verspätungen", "Der Zug kommt später als geplant."], ["umsteigen (ist umgestiegen)", "einen Zug verlassen und in einen anderen gehen"], ["der Anschluss, die Anschlüsse", "der nächste Zug auf der Reise, den man erreichen muss"], ["die Zugbegleiterin, die Zugbegleiterinnen", "Sie arbeitet im Zug und kontrolliert die Tickets."], ["ankommen (ist angekommen)", "am Ziel sein"], ["einsteigen (ist eingestiegen)", "in den Zug oder Bus gehen"], ["hin und zurück", "die Fahrt zum Ziel und wieder nach Hause"], ["der Fensterplatz, die Fensterplätze", "Sitz direkt neben dem Fenster"], ["schweigen", "nichts sagen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich habe mein Ticket online ___,", "Zehn Minuten ___ – ich habe Zeit genug.", "In Münster musste ich leider ___,", "Um drei Uhr bin ich endlich in Hamburg ___,", "Wir sind mit der ___ zu ihr gefahren,"], "solutions": ["gebucht", "Verspätung", "umsteigen", "angekommen", "U-Bahn"]}, "suno": "87e14303-4687-40f3-a2a3-b175cbd80a08"}, {"id": "a2-06-als-ich-klein-war", "level": "A2", "title": "Als ich klein war", "theme": "Kindheit und Erinnerungen", "grammar": "Präteritum von sein, haben und den Modalverben (war, hatte, konnte, wollte, musste, durfte)", "intro": "Ein Lied über Kindheit: ein kleines Dorf, ein Fahrrad, die Stimme der Mutter. Du übst das Präteritum von sein, haben und den Modalverben.", "lyrics": "[Verse 1]\nAls ich klein war, war die Welt so groß,\nich hatte ein Fahrrad und lief barfuß los.\nWir hatten kein Handy, wir hatten nur Zeit,\nder Weg zur Schule war staubig und weit.\n\n[Chorus]\nAls ich klein war, war alles leicht,\nich wollte nur spielen, bis die Sonne weicht.\nIch durfte nicht lang bleiben, ich musste nach Haus –\ndoch in meinem Herzen ist der Sommer nie aus.\n\n[Verse 2]\nMeine Mutter konnte wunderschön singen,\nmein Vater wollte mir das Schwimmen beibringen.\nIch musste früh aufstehen, ich war immer müde,\nund mein Opa hatte eine kleine Hütte.\n\n[Chorus]\nAls ich klein war, war alles leicht,\nich wollte nur spielen, bis die Sonne weicht.\nIch durfte nicht lang bleiben, ich musste nach Haus –\ndoch in meinem Herzen ist der Sommer nie aus.\n\n[Bridge]\nWar das gestern? War das ein Traum?\nIch sehe noch den alten Apfelbaum.\nHeute bin ich groß, heute bin ich hier –\naber das Kind von damals lebt noch in mir.\n\n[Chorus]\nAls ich klein war, war alles leicht,\nich wollte nur spielen, bis die Sonne weicht.\nIch durfte nicht lang bleiben, ich musste nach Haus –\ndoch in meinem Herzen ist der Sommer nie aus.", "vocab": [["die Kindheit", "die Zeit, als man ein Kind war"], ["als ich klein war", "früher, als Kind"], ["barfuß", "ohne Schuhe und ohne Socken"], ["staubig", "mit viel Staub, z. B. ein Weg ohne Asphalt"], ["weit", "nicht nah, man geht lange"], ["dürfen (durfte)", "eine Erlaubnis haben: Ich durfte spielen."], ["müssen (musste)", "es war Pflicht: Ich musste nach Hause."], ["beibringen", "jemandem etwas lehren: Er bringt mir Schwimmen bei."], ["die Hütte, die Hütten", "ein kleines, einfaches Haus"], ["der Traum, die Träume", "Bilder im Kopf beim Schlafen – oder ein großer Wunsch"], ["damals", "früher, in dieser Zeit"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich ___ ein Fahrrad und lief barfuß los.", "der Weg zur Schule war staubig und ___.", "Meine Mutter ___ wunderschön singen,", "Ich musste früh aufstehen, ich war immer ___,", "Ich sehe noch den alten ___."], "solutions": ["hatte", "weit", "konnte", "müde", "Apfelbaum"]}, "suno": "4d1b6fcd-760c-475d-bd70-c55e4c64dda6"}, {"id": "a2-07-am-liebsten", "level": "A2", "title": "Am liebsten mit dir", "theme": "Freizeit, Essen und Vorlieben", "grammar": "gern – lieber – am liebsten; Komparativ und Superlativ (schöner als, am schönsten)", "intro": "Pizza oder Suppe? Kino oder Park? Dieses Liebeslied vergleicht – und am Ende ist klar, was am schönsten ist. Du übst Komparativ und Superlativ.", "lyrics": "[Verse 1]\nIch trinke gern Kaffee, doch Tee trink ich lieber,\nich esse gern Pizza – du kochst noch viel lieber.\nDer Sommer ist schön, der Herbst ist noch schöner,\ndie Stadt ist laut, doch dein Lachen ist lauter.\n\n[Chorus]\nAm liebsten, am liebsten bin ich mit dir,\nkein Ort ist schöner als das Hier.\nDu bist größer als der Himmel, heller als das Licht –\nam liebsten mit dir, vergiss das nicht.\n\n[Verse 2]\nDer Bus ist schnell, der Zug ist schneller,\nmein Zimmer ist klein, dein Zimmer ist heller.\nIch gehe gern ins Kino, lieber in den Park,\nam liebsten tanzen wir – das macht uns stark.\n\n[Chorus]\nAm liebsten, am liebsten bin ich mit dir,\nkein Ort ist schöner als das Hier.\nDu bist größer als der Himmel, heller als das Licht –\nam liebsten mit dir, vergiss das nicht.\n\n[Bridge]\nGut – besser – am besten,\nviel – mehr – am meisten.\nIch hab dich gern, ich hab dich lieber,\nich hab dich am liebsten – immer wieder.\n\n[Chorus]\nAm liebsten, am liebsten bin ich mit dir,\nkein Ort ist schöner als das Hier.\nDu bist größer als der Himmel, heller als das Licht –\nam liebsten mit dir, vergiss das nicht.", "vocab": [["gern – lieber – am liebsten", "So sagt man, was man mag, mehr mag und am meisten mag."], ["schöner als", "Vergleich: Der Herbst ist schöner als der Sommer."], ["am schönsten", "Superlativ: Das ist das Beste von allen."], ["gut – besser – am besten", "unregelmäßige Formen"], ["viel – mehr – am meisten", "unregelmäßige Formen"], ["hell", "mit viel Licht, nicht dunkel"], ["laut", "mit viel Lärm, nicht leise"], ["schnell", "nicht langsam"], ["das Kino, die Kinos", "Hier sieht man Filme."], ["das Lachen", "So klingt es, wenn jemand lacht."], ["stark", "mit viel Kraft"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich trinke gern Kaffee, doch Tee trink ich ___,", "Der Sommer ist schön, der Herbst ist noch ___,", "Der Bus ist schnell, der Zug ist ___,", "kein Ort ist schöner ___ das Hier.", "Gut – besser – am ___,"], "solutions": ["lieber", "schöner", "schneller", "als", "besten"]}, "suno": "7715aa6c-ec7c-42ed-b809-f2bf13e58c4f"}, {"id": "a2-08-kommst-du-mit", "level": "A2", "title": "Kommst du mit?", "theme": "Sich verabreden: Einladung, Zusage, Absage, Termine", "grammar": "Reflexive Verben (sich treffen, sich freuen, sich verabreden, sich beeilen), Uhrzeit und Termine", "intro": "Samstagabend, Konzert, aber keiner hat Zeit? In diesem Lied verabreden sich Freunde – mit Zusagen, Absagen und reflexiven Verben.", "lyrics": "[Verse 1]\nIch schreibe dir: „Hast du am Samstag Zeit?\nEs gibt ein Konzert, es ist gar nicht weit.“\nDu schreibst zurück: „Am Samstag? Leider nein,\nich muss arbeiten, ich kann nicht dabei sein.“\n\n[Chorus]\nKommst du mit? Kommst du mit?\nWir treffen uns um acht – halt Schritt!\nIch freue mich auf dich, ich freue mich so sehr –\nkommst du mit? Dann ist die Nacht nicht leer.\n\n[Verse 2]\nDann frage ich Ali: „Wie wäre es mit Sonntag?“\nEr sagt: „Super Idee, ich hab frei – ich mag das!“\nWir verabreden uns am Bahnhof um sieben,\nich ziehe mich schnell an – ich will nicht zu spät kommen.\n\n[Chorus]\nKommst du mit? Kommst du mit?\nWir treffen uns um acht – halt Schritt!\nIch freue mich auf dich, ich freue mich so sehr –\nkommst du mit? Dann ist die Nacht nicht leer.\n\n[Bridge]\nBeeil dich, beeil dich, der Bus fährt gleich!\nIch melde mich, wenn ich da bin – ganz leicht.\nTut mir leid, ich verspäte mich, nur zehn Minuten –\nwartet auf mich, ich muss mich beeilen!\n\n[Chorus]\nKommst du mit? Kommst du mit?\nWir treffen uns um acht – halt Schritt!\nIch freue mich auf dich, ich freue mich so sehr –\nkommst du mit? Dann ist die Nacht nicht leer.", "vocab": [["sich verabreden", "einen Termin mit Freunden machen"], ["sich treffen", "zusammenkommen: Wir treffen uns um acht."], ["sich freuen auf", "an etwas Schönes in der Zukunft denken und glücklich sein"], ["sich beeilen", "schnell machen, weil wenig Zeit ist"], ["sich verspäten", "zu spät kommen"], ["sich melden", "anrufen oder schreiben"], ["das Konzert, die Konzerte", "Musiker spielen live vor Publikum."], ["Zeit haben", "frei sein, nichts anderes vorhaben"], ["leider nein", "freundliche Absage"], ["Wie wäre es mit …?", "So macht man einen Vorschlag."], ["frei haben", "nicht arbeiten müssen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["„Hast du am ___ Zeit?", "ich muss ___, ich kann nicht dabei sein.“", "Wir treffen uns um ___ – halt Schritt!", "Wir verabreden uns am ___ um sieben,", "Beeil dich, beeil dich, der ___ fährt gleich!"], "solutions": ["Samstag", "arbeiten", "acht", "Bahnhof", "Bus"]}, "suno": "8b3848a8-409a-4f9b-8260-33b640325ea1"}, {"id": "a2-09-nachtschicht", "level": "A2", "title": "Wenn die Stadt schläft", "theme": "Arbeit in der Nachtschicht: Arbeitsweg, Kollegen, Pause, freie Zeit", "grammar": "Nebensätze mit wenn (Zeit und Bedingung): Verb am Ende; nach dem wenn-Satz kommt das Verb zuerst (Wenn die Stadt schläft, bin ich wach.)", "intro": "Andere schlafen, du arbeitest – dieses Lied erzählt von einer Nacht im Lager. Du übst Sätze mit wenn und siehst, wo das Verb steht.", "lyrics": "[Verse 1]\nUm zehn Uhr am Abend ziehe ich die Jacke an,\ndie Straße ist nass vom Regen, ich warte auf die Bahn.\nIch habe Nachtschicht im Lager, ich packe Karton für Karton,\ndie Lampen in der Halle sind weiß – ich kenne sie schon.\n\n[Chorus]\nWenn die Stadt schläft, bin ich wach,\nwenn du träumst, denke ich an dich – die ganze Nacht.\nWenn der Morgen kommt, fahre ich nach Haus,\nund wenn du aufstehst, ruhe ich mich aus.\n\n[Verse 2]\nUm zwei Uhr machen wir Pause, wir trinken heißen Tee,\ndraußen fällt der Regen – oder ist es schon Schnee?\nMeine Kollegin Marta lacht: „Wenn du müde bist,\ndann trink noch einen Kaffee – du weißt, wie lang die Nacht ist.“\n\n[Chorus]\nWenn die Stadt schläft, bin ich wach,\nwenn du träumst, denke ich an dich – die ganze Nacht.\nWenn der Morgen kommt, fahre ich nach Haus,\nund wenn du aufstehst, ruhe ich mich aus.\n\n[Bridge]\nAm Wochenende habe ich frei,\ndann sind wir zusammen, nur wir zwei.\nWenn ich Zeit habe, gehen wir in den Park,\nund wenn du lachst, fühle ich mich stark.\n\n[Chorus]\nWenn die Stadt schläft, bin ich wach,\nwenn du träumst, denke ich an dich – die ganze Nacht.\nWenn der Morgen kommt, fahre ich nach Haus,\nund wenn du aufstehst, ruhe ich mich aus.\n\n[Outro]\nWenn die Stadt schläft, bin ich wach –\nbis morgen früh. Gute Nacht.", "vocab": [["die Nachtschicht, die Nachtschichten", "Arbeit in der Nacht"], ["das Lager, die Lager", "großer Raum oder Gebäude für Waren"], ["der Karton, die Kartons", "eine Kiste aus Pappe"], ["die Halle, die Hallen", "ein sehr großer Raum"], ["die Pause, die Pausen", "kurze Zeit ohne Arbeit"], ["der Kollege, die Kollegen / die Kollegin, die Kolleginnen", "Person, die mit mir zusammen arbeitet"], ["müde", "Ich möchte schlafen."], ["aufstehen", "aus dem Bett kommen"], ["sich ausruhen", "nichts tun, sich erholen"], ["frei haben", "nicht arbeiten müssen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["die Straße ist nass vom ___, ich warte auf die Bahn.", "Ich habe Nachtschicht im ___, ich packe Karton für Karton,", "Um zwei Uhr machen wir ___, wir trinken heißen Tee,", "Wenn der Morgen kommt, fahre ich nach ___,", "Am Wochenende habe ich ___,"], "solutions": ["Regen", "Lager", "Pause", "Haus", "frei"]}, "suno": "ce3edf27-a9cf-439e-b979-aca51639a62b"}, {"id": "a2-10-roter-schal", "level": "A2", "title": "Ein roter Schal", "theme": "Menschen beschreiben: Aussehen, Kleidung und Charakter", "grammar": "Adjektivdeklination nach dem unbestimmten Artikel im Nominativ und Akkusativ (ein dunkler Mantel, eine junge Frau, ein kleines Lächeln, einen warmen Blick)", "intro": "Spät am Abend in der Bahn sieht ein Mann eine Frau – und vergisst sie nicht mehr. Du lernst, wie du Menschen beschreibst, und übst die Adjektivendungen nach ein, eine und einen.", "lyrics": "[Verse 1]\nEs ist spät, die Bahn ist fast leer,\ndraußen fällt ein leiser Regen, die Stadt glänzt wie ein Meer.\nAm Fenster sitzt eine junge Frau, sie liest ein dickes Buch,\nich sehe sie nur kurz – und das ist schon genug.\n\n[Chorus]\nEin dunkler Mantel, ein roter Schal,\nein kleines Lächeln – nur ein einziges Mal.\nDu hast einen warmen Blick und ein freundliches Gesicht –\nwer bist du? Ich weiß es nicht.\n\n[Verse 2]\nSie hat lange, schwarze Haare und eine runde Brille,\nin der Bahn ist eine große Stille.\nIch bin ein schüchterner Mann, ich sage kein Wort,\nund an der nächsten Haltestelle steigt sie aus – sie ist fort.\n\n[Chorus]\nEin dunkler Mantel, ein roter Schal,\nein kleines Lächeln – nur ein einziges Mal.\nDu hast einen warmen Blick und ein freundliches Gesicht –\nwer bist du? Ich weiß es nicht.\n\n[Bridge]\nVielleicht sehe ich morgen ein bekanntes Gesicht,\nvielleicht sitzt sie wieder da im warmen Licht.\nDann bin ich ein mutiger Mann, dann sage ich: „Hallo!“ –\nund vielleicht hat sie ein Lächeln für mich – einfach so.\n\n[Chorus]\nEin dunkler Mantel, ein roter Schal,\nein kleines Lächeln – nur ein einziges Mal.\nDu hast einen warmen Blick und ein freundliches Gesicht –\nwer bist du? Ich weiß es nicht.\n\n[Outro]\nEin dunkler Mantel, ein roter Schal –\nbis morgen, vielleicht, noch einmal.", "vocab": [["der Mantel, die Mäntel", "eine lange, warme Jacke"], ["der Schal, die Schals", "Man trägt ihn im Winter um den Hals."], ["das Lächeln", "ein freundliches Gesicht mit kleinem Lachen"], ["der Blick, die Blicke", "wie man jemanden ansieht"], ["das Gesicht, die Gesichter", "Augen, Nase und Mund sind im Gesicht."], ["die Brille, die Brillen", "Damit sieht man besser."], ["schüchtern", "Man spricht nicht gern mit fremden Menschen."], ["mutig", "Man hat keine Angst."], ["aussteigen", "aus der Bahn oder dem Bus gehen"], ["die Haltestelle, die Haltestellen", "Hier hält der Bus oder die Bahn."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["draußen fällt ein leiser ___, die Stadt glänzt wie ein Meer.", "Am Fenster sitzt eine junge Frau, sie liest ein dickes ___,", "Sie hat lange, schwarze Haare und eine runde ___,", "ein kleines ___ – nur ein einziges Mal.", "Ich bin ein schüchterner Mann, ich sage kein ___,"], "solutions": ["Regen", "Buch", "Brille", "Lächeln", "Wort"]}, "suno": "290013bb-0100-4d0b-99fc-579cab295695"}, {"id": "b1-01-ich-bewerbe-mich", "level": "B1", "title": "Ich bewerbe mich", "theme": "Arbeit und Bewerbung: Stellenanzeige, Unterlagen, Vorstellungsgespräch", "grammar": "Nebensätze mit weil, obwohl, wenn, dass und indirekte Fragen (warum …)", "intro": "Lebenslauf, Anschreiben, Vorstellungsgespräch – dieser motivierende Hip-Hop-Song begleitet dich auf dem Weg zum neuen Job. Du übst Nebensätze mit weil, obwohl, wenn und dass.", "lyrics": "[Verse 1]\nIch sitze am Laptop, es ist schon spät,\nich schreibe eine Bewerbung, weil es um meine Zukunft geht.\nLebenslauf, Anschreiben, Zeugnisse – alles in die Mappe,\nund obwohl ich nervös bin, sage ich mir: Ich schaffe das!\nIch habe in der Anzeige gelesen, dass sie Pflegekräfte suchen,\nin Teilzeit oder Vollzeit – nicht nur träumen, sondern versuchen!\n\n[Chorus]\nWenn ich die Chance bekomme, zeige ich, was ich kann.\nIch bin pünktlich und zuverlässig – sagen Sie mir: Wann fange ich an?\nIch bewerbe mich, ich bewerbe mich,\nmit Herz und mit Erfahrung – und ich bin ehrlich.\n\n[Verse 2]\nEine Woche später kommt eine Mail – ich lese sie zweimal:\nEinladung zum Vorstellungsgespräch – ich jubele: genial!\nIch bügle mein Hemd und übe jeden Satz,\nStärken, Schwächen, Ziele – alles hat seinen Platz.\n\n[Chorus]\nWenn ich die Chance bekomme, zeige ich, was ich kann.\nIch bin pünktlich und zuverlässig – sagen Sie mir: Wann fange ich an?\nIch bewerbe mich, ich bewerbe mich,\nmit Herz und mit Erfahrung – und ich bin ehrlich.\n\n[Verse 3]\nIm Gespräch fragt die Chefin, warum ich hier bin.\nIch sage: „Weil ich Menschen helfen will – das gibt meinem Leben Sinn.\nObwohl mein Deutsch nicht perfekt ist, lerne ich jeden Tag,\nund wenn ich etwas nicht verstehe, dann frage ich nach.“\n\n[Bridge]\nSie lächelt und sagt: „Wir melden uns bei Ihnen.“\nDrei Tage später: Zusage! Jetzt kann ich mein Geld verdienen.", "vocab": [["die Bewerbung, die Bewerbungen", "Unterlagen, mit denen man sich um eine Stelle bemüht"], ["der Lebenslauf, die Lebensläufe", "tabellarische Übersicht über Schule, Ausbildung und Berufserfahrung"], ["das Anschreiben, die Anschreiben", "Brief, in dem man erklärt, warum man die Stelle möchte"], ["das Zeugnis, die Zeugnisse", "offizielles Dokument mit Noten oder einer Bewertung vom Arbeitgeber"], ["die Anzeige, die Anzeigen", "Text in der Zeitung oder im Internet: Eine Firma sucht Mitarbeitende."], ["die Pflegekraft, die Pflegekräfte", "Person, die kranke oder alte Menschen betreut"], ["zuverlässig", "Auf diese Person kann man sich verlassen."], ["das Vorstellungsgespräch, die Vorstellungsgespräche", "Treffen mit der Firma, bevor man eingestellt wird"], ["Teilzeit / Vollzeit", "weniger als / ungefähr 38 bis 40 Stunden pro Woche arbeiten"], ["die Stärke / die Schwäche", "was man gut kann / was man noch nicht so gut kann"], ["die Zusage, die Zusagen", "positive Antwort: Sie bekommen die Stelle."], ["verdienen", "Geld für Arbeit bekommen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich schreibe eine Bewerbung, weil es um meine ___ geht.", "Ich habe in der Anzeige gelesen, dass sie ___ suchen,", "Ich bügle mein ___ und übe jeden Satz,", "Im Gespräch fragt die ___, warum ich hier bin.", "___ mein Deutsch nicht perfekt ist, lerne ich jeden Tag,"], "solutions": ["Zukunft", "Pflegekräfte", "Hemd", "Chefin", "Obwohl"]}, "suno": "967c84df-bfdc-455a-87db-c0676a2eaaa2"}, {"id": "b1-02-termin-beim-amt", "level": "B1", "title": "Bitte warten", "theme": "Behörden: Bürgeramt, Ummeldung, Formulare, Dokumente", "grammar": "Passiv Präsens (wird/werden + Partizip II)", "intro": "Wartenummer ziehen, Formular ausfüllen, Stempel holen – kennst du das? Dieser ironische Funk-Song nimmt dich mit aufs Amt und trainiert das Passiv.", "lyrics": "[Verse 1]\nMontagmorgen, sieben Uhr, ich stehe vor dem Amt,\ndie Schlange ist schon lang – ich bin hellwach und angespannt.\nIch ziehe eine Nummer: Zweihundertneun,\nauf dem Bildschirm steht noch: Hundertneun.\n\n[Chorus]\nHier wird gewartet, hier wird gestempelt,\nhier wird gefragt, kopiert und abgeheftet.\nHier werden Formulare ausgefüllt und unterschrieben –\nund am Ende bin ich trotzdem freundlich geblieben.\n\n[Verse 2]\nEndlich bin ich dran: „Zimmer vierzehn, bitte sehr!“\n„Meine Adresse hat sich geändert – ich wohne dort nicht mehr.“\n„Kein Problem“, sagt der Beamte, „das wird sofort gemacht,\nauf Ihren Ausweis wird ein Aufkleber geklebt – so einfach, wer hätte das gedacht?“\n\n[Chorus]\nHier wird gewartet, hier wird gestempelt,\nhier wird gefragt, kopiert und abgeheftet.\nHier werden Formulare ausgefüllt und unterschrieben –\nund am Ende bin ich trotzdem freundlich geblieben.\n\n[Verse 3]\n„Nur eins fehlt noch“, sagt er, „das tut mir wirklich leid:\nDie Bestätigung vom Vermieter wird noch benötigt – Sie haben dafür zwei Wochen Zeit.“\n\n[Bridge]\nIch atme tief ein und ich atme aus,\nich hole das Papier und laufe schnell nach Haus.\nAm nächsten Tag bin ich wieder hier –\nNummer zweihundertzehn – und diesmal klappt es mit mir!\n\n[Chorus]\nHier wird gewartet, hier wird gestempelt,\nhier wird gefragt, kopiert und abgeheftet.\nHier werden Formulare ausgefüllt und unterschrieben –\nund am Ende bin ich trotzdem freundlich geblieben.\n\n[Outro]\nAlles wird erledigt – irgendwann.\nBitte warten. Bitte warten.", "vocab": [["das Amt, die Ämter", "staatliches Büro, z. B. das Bürgeramt"], ["die Schlange, die Schlangen", "hier: viele Menschen, die hintereinander warten"], ["eine Nummer ziehen", "am Automaten ein Papier mit einer Wartenummer nehmen"], ["das Formular, die Formulare", "offizielles Papier mit Feldern für Name, Adresse usw."], ["ausfüllen", "die leeren Felder in einem Dokument beschriften"], ["unterschreiben", "seinen Namen mit der Hand unter ein Dokument setzen"], ["stempeln", "ein offizielles Zeichen mit Farbe auf ein Dokument drücken"], ["der Beamte, die Beamten (ein Beamter)", "Person, die für den Staat arbeitet, z. B. im Bürgeramt"], ["der Ausweis, die Ausweise", "Dokument mit Foto, das zeigt, wer man ist"], ["abheften", "Papiere in einen Ordner legen"], ["benötigen", "brauchen (formell)"], ["erledigen", "eine Aufgabe fertig machen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich ziehe eine ___: Zweihundertneun,", "Hier werden Formulare ___ und unterschrieben –", "„Meine ___ hat sich geändert – ich wohne dort nicht mehr.“", "auf Ihren Ausweis wird ein ___ geklebt – so einfach, wer hätte das gedacht?“", "Ich atme ___ ein und ich atme aus,"], "solutions": ["Nummer", "ausgefüllt", "Adresse", "Aufkleber", "tief"]}, "suno": "794b6a6b-8b28-4223-b2a0-04b302fbe879"}, {"id": "b1-03-kleine-schritte", "level": "B1", "title": "Kleine Schritte", "theme": "Umwelt und Klimaschutz im Alltag", "grammar": "Konjunktiv II: Wünsche (Ich wünschte, …), irreale Bedingungen (Wenn …, würde …), Ratschläge (An deiner Stelle würde ich …, Du solltest …)", "intro": "Was kann ein einzelner Mensch für die Umwelt tun? Dieser hoffnungsvolle Folk-Song gibt Antworten – und du übst Wünsche und Ratschläge im Konjunktiv II.", "lyrics": "[Verse 1]\nIch stehe morgens an der Ruhr, das Wasser fließt so still,\nich frage mich, was ich für diese Erde tun kann und tun will.\nIch fahre mit dem Fahrrad, das Auto bleibt zu Haus,\nich trenne meinen Müll – Papier, Glas, Bio – und bringe ihn raus.\n\n[Chorus]\nKleine Schritte, große Sachen,\nich wünschte, alle würden mitmachen!\nWenn ich die Welt verändern könnte,\nwürde ich bei mir beginnen –\ndenn jeder kleine Schritt zählt,\nund gemeinsam können wir gewinnen.\n\n[Verse 2]\nIm Winter gibt es Erdbeeren, geflogen um die halbe Welt,\nich kaufe lieber regional – das spart CO2 und auch Geld.\nMein Nachbar sagt: „Was bringt das schon? Du allein bist viel zu klein.“\nIch sage: „Wenn alle so denken würden, würde nie etwas anders sein.“\n\n[Chorus]\nKleine Schritte, große Sachen,\nich wünschte, alle würden mitmachen!\nWenn ich die Welt verändern könnte,\nwürde ich bei mir beginnen –\ndenn jeder kleine Schritt zählt,\nund gemeinsam können wir gewinnen.\n\n[Bridge]\nAn deiner Stelle würde ich öfter Bahn fahren,\nan deiner Stelle würde ich Wasser und Strom sparen.\nDu solltest nicht alles kaufen, was die Werbung dir verspricht –\ndie Erde brauchen wir, einen Planeten B gibt es nicht.\n\n[Chorus]\nKleine Schritte, große Sachen,\nich wünschte, alle würden mitmachen!\nWenn ich die Welt verändern könnte,\nwürde ich bei mir beginnen –\ndenn jeder kleine Schritt zählt,\nund gemeinsam können wir gewinnen.", "vocab": [["die Umwelt", "Natur, Luft, Wasser und Boden um uns herum"], ["den Müll trennen", "Papier, Glas, Plastik und Bioabfall in verschiedene Tonnen werfen"], ["regional", "aus der Nähe, aus der eigenen Gegend"], ["das CO2 (Kohlendioxid)", "Gas, das beim Verbrennen von Benzin oder Kohle entsteht und das Klima erwärmt"], ["sparen", "weniger verbrauchen oder ausgeben"], ["die Werbung", "Reklame: Firmen zeigen Produkte, damit man sie kauft"], ["versprechen", "sagen, dass etwas sicher passiert"], ["an deiner Stelle", "wenn ich du wäre"], ["der Planet, die Planeten", "Himmelskörper wie die Erde oder der Mars"], ["verändern", "anders machen"], ["mitmachen", "bei einer Aktion dabei sein und helfen"], ["der Strom", "Energie aus der Steckdose"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich fahre mit dem ___, das Auto bleibt zu Haus,", "ich ___ meinen Müll – Papier, Glas, Bio – und bringe ihn raus.", "ich wünschte, alle würden ___!", "ich kaufe lieber ___ – das spart CO2 und auch Geld.", "an deiner Stelle würde ich Wasser und ___ sparen."], "solutions": ["Fahrrad", "trenne", "mitmachen", "regional", "Strom"]}, "suno": "86e74151-b1fc-47a8-9324-8220ab24be3b"}, {"id": "b1-04-lass-uns-reden", "level": "B1", "title": "Lass uns reden", "theme": "Freundschaft und Konflikte: Streit, Entschuldigung, Versöhnung", "grammar": "Relativsätze (Relativpronomen im Nominativ, Akkusativ, Dativ, mit Präposition)", "intro": "Ein Streit unter Freunden – und dann? Dieses Pop-Rock-Duett erzählt von Streit und Versöhnung. Du übst dabei Relativsätze.", "lyrics": "[Verse 1]\nDu bist die Freundin, die immer für mich da war,\ndie mit mir gelacht und geweint hat, Jahr für Jahr.\nDoch letzte Woche hast du etwas gesagt,\ndas mich verletzt hat – ich habe nicht nachgefragt.\nIch habe geschwiegen, ich war sauer und gekränkt,\nund dachte an die Jahre, die das Leben uns schenkt.\n\n[Chorus]\nLass uns reden, lass uns ehrlich sein,\nein Streit ist doch kein Grund, allein zu sein.\nDu bist der Mensch, dem ich vertraue,\ndie Brücke, auf die ich baue.\n\n[Verse 2]\nIch habe auch gemerkt, dass ich zu laut war,\ndie Worte, die ich sagte, waren unfair – das ist mir jetzt klar.\nWeißt du noch, das Café, in dem wir immer saßen,\nin dem wir die ganze Welt und auch die Zeit vergaßen?\n\n[Chorus]\nLass uns reden, lass uns ehrlich sein,\nein Streit ist doch kein Grund, allein zu sein.\nDu bist der Mensch, dem ich vertraue,\ndie Brücke, auf die ich baue.\n\n[Bridge]\nEs tut mir leid. – Mir tut es auch leid.\nIch habe dich vermisst, die ganze Zeit.\nFreunde, mit denen man streiten kann,\nsind Freunde, die bleiben – von jetzt an.\n\n[Chorus]\nLass uns reden, lass uns ehrlich sein,\nein Streit ist doch kein Grund, allein zu sein.\nDu bist der Mensch, dem ich vertraue,\ndie Brücke, auf die ich baue.\n\n[Outro]\nDu bist der Mensch, dem ich vertraue.", "vocab": [["der Streit, die Streitigkeiten", "lauter Konflikt, Meinungsverschiedenheit"], ["verletzen", "hier: jemandem mit Worten wehtun"], ["sauer sein (ugs.)", "wütend, verärgert sein"], ["gekränkt", "traurig, weil jemand etwas Böses gesagt oder getan hat"], ["schweigen", "nichts sagen, still sein"], ["ehrlich", "offen, die Wahrheit sagend"], ["vertrauen (+ Dativ)", "sicher sein, dass jemand nichts Böses tut"], ["auf jemanden bauen", "sich auf jemanden verlassen"], ["merken", "etwas wahrnehmen, plötzlich verstehen"], ["die Brücke, die Brücken", "Weg über einen Fluss; hier: Verbindung zwischen Menschen"], ["vergessen (vergaß, hat vergessen)", "nicht mehr an etwas denken"], ["sich entschuldigen", "sagen: Es tut mir leid."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Du bist die ___, die immer für mich da war,", "das mich ___ hat – ich habe nicht nachgefragt.", "Du bist der Mensch, ___ ich vertraue,", "Weißt du noch, das ___, in dem wir immer saßen,", "Freunde, mit ___ man streiten kann,"], "solutions": ["Freundin", "verletzt", "dem", "Café", "denen"]}, "suno": "6c9d3ac3-84f9-4b25-988d-85ff256835f8"}, {"id": "b1-05-zwei-zuhause", "level": "B1", "title": "Zwei Zuhause", "theme": "Heimat und Ankommen: Erinnerungen, Familie im Herkunftsland, neues Leben im Ruhrgebiet", "grammar": "Konjunktiv II für Wünsche (Wenn ich doch …, Ich wünschte …, Ich hätte gern …); temporale Nebensätze mit als und seit", "intro": "Was ist Heimat – ein Ort oder ein Gefühl? Diese berührende Ballade erzählt vom Ankommen im Ruhrgebiet. Du übst Wünsche im Konjunktiv II und Sätze mit als und seit.", "lyrics": "[Verse 1]\nAls ich ankam, war der Himmel grau,\nich kannte keine Wörter, keinen Weg – ich wusste nichts genau.\nSeit ich hier bin, ist so viel passiert,\nich habe gelernt, gearbeitet, gekämpft und viel probiert.\n\n[Chorus]\nIch habe zwei Zuhause, zwei Sprachen in mir,\nein Teil von mir ist dort, ein Teil ist hier.\nWenn ich doch Flügel hätte, wäre ich morgens bei dir\nund abends wieder hier.\n\n[Verse 2]\nMeine Mutter ruft mich an und fragt: „Geht es dir gut?“\nIch sage: „Ja, Mama“ – doch manchmal fehlt mir der Mut.\nIch hätte gern ihr Essen, ihren Tee und ihren Rat\nund den Markt am Morgen in meiner alten Stadt.\n\n[Chorus]\nIch habe zwei Zuhause, zwei Sprachen in mir,\nein Teil von mir ist dort, ein Teil ist hier.\nWenn ich doch Flügel hätte, wäre ich morgens bei dir\nund abends wieder hier.\n\n[Verse 3]\nDoch hier habe ich Freunde, eine Arbeit und ein Ziel,\ndie Nachbarin sagt „Glück auf!“ – und das bedeutet viel.\nIch wünschte, du könntest sehen, wie ich lebe und lache,\nund dass ich jetzt auf Deutsch träume – und manchmal Fehler mache.\n\n[Bridge]\nHeimat ist kein Ort, Heimat ist ein Gefühl,\nmal ist es warm und mal ist es kühl.\nHeimat ist dort, wo man mich versteht,\nwo jemand auf mich wartet, wenn es spät ist.\n\n[Outro]\nZwei Zuhause … und ein Herz.", "vocab": [["ankommen (kam an, ist angekommen)", "an einem neuen Ort eintreffen; hier auch: sich einleben"], ["die Heimat", "Ort oder Land, aus dem man kommt oder wo man sich zu Hause fühlt"], ["der Flügel, die Flügel", "Teil von einem Vogel oder Flugzeug zum Fliegen"], ["der Rat", "Tipp, Empfehlung von einer anderen Person"], ["das Ziel, die Ziele", "das, was man erreichen möchte"], ["Glück auf!", "traditioneller Gruß der Bergleute im Ruhrgebiet"], ["das Gefühl, die Gefühle", "Emotion, z. B. Freude, Angst oder Liebe"], ["kämpfen", "hier: sich sehr anstrengen, um etwas zu schaffen"], ["probieren", "etwas Neues versuchen oder testen"], ["träumen", "im Schlaf Bilder sehen; sich etwas sehr wünschen"], ["der Mut", "innere Stärke, keine Angst haben"], ["seit", "von einem Zeitpunkt in der Vergangenheit bis jetzt"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Als ich ankam, war der Himmel ___,", "___ ich hier bin, ist so viel passiert,", "Wenn ich doch ___ hätte, wäre ich morgens bei dir", "die ___ sagt „Glück auf!“ – und das bedeutet viel.", "Heimat ist kein Ort, Heimat ist ein ___,"], "solutions": ["grau", "Seit", "Flügel", "Nachbarin", "Gefühl"]}, "suno": "ada65927-853a-49ab-8e9f-28a1dcb3fe58"}, {"id": "b1-06-das-paket", "level": "B1", "title": "Das Paket, das nie kam", "theme": "Online-Einkauf, Lieferung und Reklamation", "grammar": "Präteritum beim Erzählen; Plusquamperfekt mit nachdem (Nachdem ich bestellt hatte, …)", "intro": "Bestellt, bezahlt – und dann? Diese Geschichte erzählt von einem Paket, das nie ankam. Du übst das Erzählen im Präteritum und Sätze mit nachdem.", "lyrics": "[Verse 1]\nEs war ein Montag im November, kalt und grau,\nich bestellte eine Jacke – warm und dunkelblau.\nNachdem ich online bezahlt hatte, kam eine Mail:\n„Ihr Paket ist unterwegs – es kommt ganz schnell.“\n\n[Chorus]\nIch wartete und wartete, Tag für Tag,\ndie Sendungsnummer zeigte nur: „Zugestellt“ – doch nichts lag\nvor meiner Tür, nicht im Flur, nicht beim Nachbarn nebenan –\ndas Paket, das nie kam.\n\n[Verse 2]\nNachdem ich drei Tage gewartet hatte, rief ich an,\ndie Hotline spielte Musik – eine Stunde lang.\nEine Frau sagte endlich: „Das tut mir wirklich leid,\nwir prüfen das sofort, das braucht ein bisschen Zeit.“\n\n[Chorus]\nIch wartete und wartete, Tag für Tag,\ndie Sendungsnummer zeigte nur: „Zugestellt“ – doch nichts lag\nvor meiner Tür, nicht im Flur, nicht beim Nachbarn nebenan –\ndas Paket, das nie kam.\n\n[Bridge]\nIch schrieb eine Reklamation, höflich, aber klar:\n„Bitte erstatten Sie den Betrag – das wäre wunderbar.“\nZwei Wochen später kam das Geld auf mein Konto zurück –\nund im Frühling klingelte es: Da war die Jacke. Was für ein Glück!\n\n[Outro]\nDas Paket, das nie kam –\nkam im Frühling an.", "vocab": [["bestellen", "Ware kaufen, die geliefert wird, z. B. online"], ["unterwegs sein", "auf dem Weg sein, noch nicht angekommen"], ["die Sendungsnummer", "Nummer, mit der man das Paket online verfolgt"], ["zugestellt", "geliefert, beim Empfänger angekommen"], ["der Flur, die Flure", "der Gang im Haus oder in der Wohnung"], ["der Nachbar, die Nachbarn", "Person, die nebenan wohnt"], ["die Hotline, die Hotlines", "Telefonnummer für Kundenservice"], ["prüfen", "kontrollieren, genau ansehen"], ["die Reklamation, die Reklamationen", "Beschwerde, weil eine Ware fehlt oder kaputt ist"], ["erstatten", "Geld zurückgeben"], ["der Betrag, die Beträge", "eine Summe Geld"], ["das Konto, die Konten", "Hier liegt mein Geld bei der Bank."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich bestellte eine ___ – warm und dunkelblau.", "Nachdem ich online ___ hatte, kam eine Mail:", "die ___ spielte Musik – eine Stunde lang.", "Ich schrieb eine ___, höflich, aber klar:", "Zwei Wochen später kam das Geld auf mein ___ zurück –"], "solutions": ["Jacke", "bezahlt", "Hotline", "Reklamation", "Konto"]}, "suno": "813498ce-c42d-4010-9b78-4f8ea4b3511c"}, {"id": "b1-07-zu-viel-zu-schnell", "level": "B1", "title": "Zu viel, zu schnell", "theme": "Stress im Alltag, Pausen und Gesundheit", "grammar": "Infinitiv mit zu (Es ist schwer, … zu …; Ich versuche, … zu …; Ich habe keine Lust, … zu …)", "intro": "Arbeit, Kurs, Familie, Termine – manchmal ist alles zu viel. Dieses ruhige Lied erzählt von Stress und davon, Pausen zu machen. Du übst den Infinitiv mit zu.", "lyrics": "[Verse 1]\nDer Wecker klingelt, es ist kurz nach fünf,\nich versuche, wach zu werden – ich bin müde bis zum Strumpf.\nIch vergesse, zu frühstücken, ich renne zum Bus,\nes ist nicht leicht, alles zu schaffen – ich weiß nur: Ich muss.\n\n[Chorus]\nZu viel, zu schnell, zu laut, zu grell –\nich habe keine Lust, immer weiterzulaufen.\nEs ist Zeit, still zu sein, es ist Zeit, durchzuatmen –\nzu viel, zu schnell – ich lerne, langsam zu leben.\n\n[Verse 2]\nMeine Chefin bittet mich, länger zu bleiben,\nmein Sohn wartet darauf, mit mir Hausaufgaben zu schreiben.\nIch habe vergessen, meine Mutter anzurufen,\nund keine Zeit, mich auf das Sofa zu legen und auszuruhen.\n\n[Chorus]\nZu viel, zu schnell, zu laut, zu grell –\nich habe keine Lust, immer weiterzulaufen.\nEs ist Zeit, still zu sein, es ist Zeit, durchzuatmen –\nzu viel, zu schnell – ich lerne, langsam zu leben.\n\n[Bridge]\nIch habe beschlossen, Nein zu sagen,\nnicht alles allein auf meinen Schultern zu tragen.\nEs macht mir Spaß, im Park spazieren zu gehen,\nund ich höre auf, nur auf die Uhr zu sehen.\n\n[Chorus]\nZu viel, zu schnell, zu laut, zu grell –\nich habe keine Lust, immer weiterzulaufen.\nEs ist Zeit, still zu sein, es ist Zeit, durchzuatmen –\nzu viel, zu schnell – ich lerne, langsam zu leben.", "vocab": [["der Stress", "Druck und Anspannung, weil man zu viel zu tun hat"], ["der Wecker, die Wecker", "Uhr, die morgens klingelt"], ["versuchen", "probieren, sich bemühen"], ["schaffen", "etwas erfolgreich fertig machen"], ["keine Lust haben", "etwas nicht machen wollen"], ["durchatmen", "tief ein- und ausatmen, sich beruhigen"], ["grell", "sehr hell, unangenehm für die Augen"], ["bitten (um)", "höflich fragen, ob jemand etwas tut"], ["sich ausruhen", "eine Pause machen, sich erholen"], ["beschließen", "sich entscheiden"], ["Nein sagen", "eine Bitte ablehnen"], ["aufhören", "etwas nicht mehr machen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich versuche, wach zu ___ – ich bin müde bis zum Strumpf.", "Ich vergesse, zu ___, ich renne zum Bus,", "Meine Chefin bittet mich, länger zu ___,", "Ich habe beschlossen, ___ zu sagen,", "Es macht mir Spaß, im Park ___ zu gehen,"], "solutions": ["werden", "frühstücken", "bleiben", "Nein", "spazieren"]}, "suno": "9e3baa40-62d9-4b26-abd8-660b39d8ab83"}, {"id": "b1-08-wir-machen-mit", "level": "B1", "title": "Wir machen mit", "theme": "Ehrenamt und Engagement: Nachbarschaft, Verein, Tafel", "grammar": "Verben mit Präpositionen und Präpositionaladverbien (sich kümmern um – darum/worum, warten auf – darauf/worauf)", "intro": "Gemeinsam ist man stärker: Nachbarn kümmern sich um einen Garten, helfen bei der Tafel und im Sportverein. Du übst Verben mit Präpositionen und Wörter wie darauf und worüber.", "lyrics": "[Verse 1]\nIn unserer Straße gab es einen leeren Platz,\nwir haben uns geärgert über Müll und Matsch.\nDann hat Frau Öztürk gesagt: „Ich kümmere mich darum!“\nund heute wachsen Blumen – frag nicht warum.\n\n[Chorus]\nWir machen mit, wir machen mit,\nwir denken an die anderen – Schritt für Schritt.\nWorauf wartest du? Komm, mach mit –\nwir freuen uns darauf: Das ist unser Hit!\n\n[Verse 2]\nAm Samstag helfe ich bei der Tafel mit,\nich interessiere mich für Menschen – und für ihren Appetit.\nMein Nachbar trainiert die Kinder im Verein,\nsie freuen sich auf jedes Spiel und wollen dabei sein.\n\n[Chorus]\nWir machen mit, wir machen mit,\nwir denken an die anderen – Schritt für Schritt.\nWorauf wartest du? Komm, mach mit –\nwir freuen uns darauf: Das ist unser Hit!\n\n[Bridge]\nWorüber sprichst du? – Über unser Fest.\nWofür sammelst du? – Für den Rest.\nWomit kann ich helfen? – Mit deiner Zeit.\nDarauf kommt es an – wir sind bereit!\n\n[Chorus]\nWir machen mit, wir machen mit,\nwir denken an die anderen – Schritt für Schritt.\nWorauf wartest du? Komm, mach mit –\nwir freuen uns darauf: Das ist unser Hit!", "vocab": [["das Ehrenamt", "Arbeit ohne Geld, um anderen zu helfen"], ["sich engagieren", "aktiv mitmachen und helfen"], ["sich ärgern über", "wütend sein wegen einer Sache"], ["sich kümmern um", "für jemanden oder etwas sorgen"], ["die Tafel", "Organisation, die Lebensmittel an Menschen mit wenig Geld verteilt"], ["sich interessieren für", "etwas spannend finden"], ["der Verein, die Vereine", "eine Gruppe mit gemeinsamen Hobbys, z. B. Sportverein"], ["trainieren", "üben, Sport machen und anleiten"], ["sich freuen auf", "an etwas Schönes in der Zukunft denken"], ["warten auf", "Zeit vergehen lassen, bis etwas kommt"], ["sammeln", "Dinge oder Geld zusammenbringen"], ["Darauf kommt es an.", "Das ist das Wichtigste."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["wir haben uns geärgert über Müll und ___.", "Dann hat Frau Öztürk gesagt: „Ich kümmere mich ___!“", "Am Samstag helfe ich bei der ___ mit,", "Mein Nachbar trainiert die Kinder im ___,", "___ kann ich helfen? – Mit deiner Zeit."], "solutions": ["Matsch", "darum", "Tafel", "Verein", "Womit"]}, "suno": "64f12bae-7c1d-4803-9b88-b715b163025d"}, {"id": "b1-09-fuehrerschein", "level": "B1", "title": "Trotz des Regens", "theme": "Führerschein in Deutschland: Fahrstunden, Theorieprüfung, praktische Prüfung", "grammar": "Präpositionen mit Genitiv (während, trotz, wegen, statt, innerhalb, außerhalb)", "intro": "Fahrstunden im Regen, die Theorie am Computer und dann die große Prüfung – dieses Lied erzählt vom Weg zum deutschen Führerschein. Du übst Präpositionen mit Genitiv wie während, trotz, wegen und statt.", "lyrics": "[Verse 1]\nDienstagabend, halb acht, die Straßen glänzen nass,\nmein Fahrlehrer sagt ruhig: „Jetzt bitte etwas mehr Gas.“\nWährend der ersten Stunde war mein Herz so laut,\nich habe statt des Spiegels nur nach vorn geschaut.\n\n[Chorus]\nTrotz des Regens, trotz der Angst – ich fahre los,\nwährend der Fahrt durch die Lichter ist die Stadt so groß.\nWegen des Traums von Freiheit gebe ich nicht auf –\ntrotz des Regens, trotz der Angst: Ich fahre los.\n\n[Verse 2]\nInnerhalb eines Monats hatte ich die Theorie,\ndreißig Fragen am Computer – so nervös war ich noch nie.\nWegen eines Fehlers fiel ich beim ersten Mal durch,\nbeim zweiten Mal bestanden – und weg war meine Furcht.\n\n[Chorus]\nTrotz des Regens, trotz der Angst – ich fahre los,\nwährend der Fahrt durch die Lichter ist die Stadt so groß.\nWegen des Traums von Freiheit gebe ich nicht auf –\ntrotz des Regens, trotz der Angst: Ich fahre los.\n\n[Bridge]\nPrüfungstag im Februar, außerhalb der Stadt,\ndie Landstraße ist dunkel, der Asphalt ist glatt.\nDer Prüfer schreibt und schweigt – dann lächelt er mich an:\n„Herzlichen Glückwunsch, bestanden!“ – und mein neues Leben fängt an.\n\n[Chorus]\nTrotz des Regens, trotz der Angst – ich fahre los,\nwährend der Fahrt durch die Lichter ist die Stadt so groß.\nWegen des Traums von Freiheit gebe ich nicht auf –\ntrotz des Regens, trotz der Angst: Ich fahre los.\n\n[Outro]\nTrotz des Regens …\nich fahre los.", "vocab": [["der Führerschein, die Führerscheine", "Dokument, mit dem man Auto fahren darf"], ["der Fahrlehrer, die Fahrlehrer", "Person, die in der Fahrschule das Autofahren unterrichtet"], ["Gas geben", "schneller fahren"], ["der Spiegel, die Spiegel", "Glas, in dem man sieht, was hinter dem Auto ist"], ["die Theorie", "hier: Prüfung mit Fragen zu Verkehrsregeln"], ["durchfallen", "eine Prüfung nicht schaffen"], ["bestehen", "eine Prüfung schaffen"], ["die Furcht", "die Angst"], ["die Landstraße, die Landstraßen", "Straße außerhalb der Stadt zwischen Orten"], ["glatt", "so, dass man leicht rutscht, z. B. bei Eis oder Regen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich habe statt des ___ nur nach vorn geschaut.", "___ des Regens, trotz der Angst – ich fahre los,", "Innerhalb eines ___ hatte ich die Theorie,", "Wegen eines Fehlers fiel ich beim ersten Mal ___,", "Prüfungstag im Februar, ___ der Stadt,"], "solutions": ["Spiegels", "Trotz", "Monats", "durch", "außerhalb"]}, "suno": "264926f8-3f4f-4919-982d-897e733a7d7b"}, {"id": "b1-10-nicht-nur-ein-zimmer", "level": "B1", "title": "Nicht nur ein Zimmer", "theme": "Wohnungssuche: Anzeigen, Besichtigung, Unterlagen", "grammar": "Zweiteilige Konnektoren (nicht nur … sondern auch, sowohl … als auch, weder … noch, entweder … oder)", "intro": "Nachts Anzeigen lesen, samstags Besichtigung mit dreißig anderen Leuten – kennst du das auch? In diesem Lied suchst du mit nach einer Wohnung und übst zweiteilige Konnektoren wie weder … noch und sowohl … als auch.", "lyrics": "[Verse 1]\nEs ist nach Mitternacht, mein Handy leuchtet blau,\nich lese Wohnungsanzeigen, draußen ist es nass und grau.\nDie eine ist weder hell noch ruhig – sie liegt direkt am Gleis,\ndie andere hat sowohl Balkon als auch Garten – doch zu welchem Preis?\n\n[Chorus]\nNicht nur ein Zimmer, sondern auch ein Zuhause –\nweder zu laut noch zu dunkel, und abends komm ich nach Hause.\nEntweder find ich es bald, oder ich suche weiter –\nirgendwo brennt ein Fenster für mich, hell und heiter.\n\n[Verse 2]\nAm Samstag ist Besichtigung: dreißig Leute auf der Treppe,\nich habe sowohl Gehaltsnachweise als auch die Schufa in der Mappe.\nDer Makler sagt: „Entweder Sie entscheiden sich sofort, oder Sie sind raus.“\nIch gehe in den Regen und atme langsam aus.\n\n[Chorus]\nNicht nur ein Zimmer, sondern auch ein Zuhause –\nweder zu laut noch zu dunkel, und abends komm ich nach Hause.\nEntweder find ich es bald, oder ich suche weiter –\nirgendwo brennt ein Fenster für mich, hell und heiter.\n\n[Bridge]\nAm Montag klingelt mein Telefon, eine ältere Dame spricht:\n„Die Wohnung ist weder neu noch groß – aber sie hat viel Licht.“\nIch sehe vom Fenster sowohl den Park als auch die Bahn,\nund in der ersten Nacht komme ich endlich bei mir an.\n\n[Chorus]\nNicht nur ein Zimmer, sondern auch ein Zuhause –\nweder zu laut noch zu dunkel, und abends komm ich nach Hause.\nEntweder find ich es bald, oder ich suche weiter –\nirgendwo brennt ein Fenster für mich, hell und heiter.\n\n[Outro]\nNicht nur ein Zimmer,\nsondern auch ein Zuhause.", "vocab": [["die Wohnungsanzeige, die Wohnungsanzeigen", "Text im Internet oder in der Zeitung: Eine Wohnung ist frei."], ["leuchten", "hell sein, Licht geben"], ["das Gleis, die Gleise", "Schienen, auf denen Züge und Bahnen fahren"], ["die Besichtigung, die Besichtigungen", "Termin, bei dem man sich eine Wohnung ansieht"], ["der Gehaltsnachweis, die Gehaltsnachweise", "Dokument, das zeigt, wie viel Geld man verdient"], ["die Schufa", "Auskunft, ob man seine Rechnungen immer bezahlt hat"], ["die Mappe, die Mappen", "Hülle für Dokumente und Papiere"], ["der Makler, die Makler", "Person, die Wohnungen vermittelt und dafür Geld bekommt"], ["sich entscheiden", "eine Wahl treffen"], ["ankommen (bei sich)", "hier: sich endlich wohl und zu Hause fühlen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich lese ___, draußen ist es nass und grau.", "Die eine ist weder hell ___ ruhig – sie liegt direkt am Gleis,", "ich habe sowohl Gehaltsnachweise ___ die Schufa in der Mappe.", "___ find ich es bald, oder ich suche weiter –", "Ich sehe vom Fenster sowohl den Park als auch die ___,"], "solutions": ["Wohnungsanzeigen", "noch", "als auch", "Entweder", "Bahn"]}, "suno": "8bade26c-0cac-4fc8-aa4c-5f10d3855d67"}, {"id": "b2-01-montagsmeeting", "level": "B2", "title": "Montagsmeeting", "theme": "Teamarbeit und Meetings: Aufgaben, Verantwortung, Fristen", "grammar": "Passiv mit Modalverb (muss erledigt werden, könnten verteilt werden)", "intro": "Montag, neun Uhr, Konferenzraum drei: Keiner fühlt sich zuständig. Dieser Synth-Pop-Song zeigt, wie aus Chaos Teamarbeit wird – mit viel Passiv mit Modalverb.", "lyrics": "[Verse 1]\nMontag, neun Uhr, Konferenzraum drei,\nder Beamer brummt, der Kaffee ist kalt – und alle sind dabei.\nDie Chefin teilt die Tagesordnung aus, Punkt für Punkt,\ndas Projekt hängt hinterher – und keiner kennt den Grund.\n\n[Pre-Chorus]\nDer Bericht muss bis Freitag fertiggestellt werden,\ndie Zahlen müssen noch geprüft werden,\nder Kunde soll heute noch informiert werden –\ndoch wer macht das? Alle schauen auf ihre Bildschirme.\n\n[Chorus]\nDas muss erledigt werden – aber wer fängt an?\nDas kann geschafft werden, wenn jeder gibt, was er kann.\nEin Team ist mehr als jeder Einzelne allein,\nwir müssen nicht perfekt, nur ehrlich miteinander sein.\n\n[Verse 2]\nHerr Krämer sagt: „Das stand nicht in meiner Mail!“\nFrau Yilmaz seufzt: „Dann haben wir ein Problem – und zwar im Detail.“\nDie Verantwortung wird hin- und hergeschoben,\nund das Problem wird wieder auf nächste Woche verschoben.\n\n[Chorus]\nDas muss erledigt werden – aber wer fängt an?\nDas kann geschafft werden, wenn jeder gibt, was er kann.\nEin Team ist mehr als jeder Einzelne allein,\nwir müssen nicht perfekt, nur ehrlich miteinander sein.\n\n[Bridge]\nDann sagt die Neue leise: „Darf ich etwas vorschlagen?\nDie Aufgaben könnten fair verteilt werden, dann muss keiner alles tragen.\nEin Board an der Wand, zehn Minuten jeden Tag:\nWer macht was bis wann – und wer braucht noch einen Rat?“\nAlle schauen sich an, dann nickt die Chefin: „So wird’s gemacht.“\nZum ersten Mal seit Wochen wird im Meeting gelacht.\n\n[Outro]\nDas kann geschafft werden – Hand in Hand.", "vocab": [["die Tagesordnung, die Tagesordnungen", "Liste der Themen, die in einer Sitzung besprochen werden"], ["hinterherhängen (ugs.)", "langsamer sein als geplant, im Rückstand sein"], ["fertigstellen", "eine Arbeit abschließen, vollenden"], ["der Bericht, die Berichte", "schriftliche Darstellung von Ergebnissen oder Ereignissen"], ["prüfen", "kontrollieren, ob etwas korrekt ist"], ["die Verantwortung", "die Pflicht, für eine Aufgabe und ihre Folgen einzustehen"], ["etwas hin- und herschieben", "hier: eine Aufgabe immer an andere weitergeben"], ["verschieben", "auf einen späteren Zeitpunkt legen"], ["vorschlagen", "eine Idee oder Lösung anbieten"], ["verteilen", "aufteilen und an mehrere Personen geben"], ["die Frist, die Fristen", "Zeitpunkt, bis zu dem etwas fertig sein muss"], ["nicken", "den Kopf kurz nach unten bewegen, um Zustimmung zu zeigen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Der Bericht muss bis Freitag ___ werden,", "die Zahlen müssen noch ___ werden,", "Das kann geschafft werden, wenn jeder ___, was er kann.", "und das Problem wird wieder auf nächste Woche ___.", "Die Aufgaben könnten fair ___ werden, dann muss keiner alles tragen."], "solutions": ["fertiggestellt", "geprüft", "gibt", "verschoben", "verteilt"]}, "suno": "5f30763c-3eea-4475-9c08-3f312ac8bc1b"}, {"id": "b2-02-ihr-anliegen", "level": "B2", "title": "Ihr Anliegen ist uns wichtig", "theme": "Kundenkontakt und Beschwerde: Reklamation, Deeskalation, Lösungen", "grammar": "Redemittel für Beschwerde und Reaktion; Konjunktiv II der Höflichkeit (Könnten Sie …? Ich wäre Ihnen dankbar, wenn …); zweiteilige Konnektoren (entweder … oder, nicht nur … sondern auch)", "intro": "Eine Waschmaschine, die nie kommt, und ein Kundenservice unter Druck: Dieses Swing-Duett zeigt, wie man sich höflich, aber bestimmt beschwert – und wie man professionell reagiert.", "lyrics": "[Verse 1]\nIch habe vor drei Wochen eine Waschmaschine bestellt,\ngeliefert wurde nichts – doch abgebucht wurde mein Geld!\nIch habe angerufen, geschrieben, gehofft,\nin Ihrer Warteschleife hing ich stundenlang – und das oft.\nIch möchte mich beschweren, und zwar in aller Form:\nIhr Service ist, mit Verlaub, eine Zumutung – enorm!\n\n[Chorus]\n„Ich verstehe Ihren Ärger, das tut mir wirklich leid,\nich kümmere mich persönlich drum – es dauert keine Ewigkeit.\nIhr Anliegen ist uns wichtig, wir finden einen Weg,\ndamit Ihre Zufriedenheit wieder an erster Stelle steht.“\n\n[Verse 2]\n„Das hat man mir zweimal versprochen – und nichts ist passiert.\nEntweder kommt die Maschine bis Freitag, oder der Kauf wird storniert!\nKönnten Sie mir bitte sagen, wer dafür verantwortlich ist?\nIch wäre Ihnen dankbar, wenn das schnell geklärt würde – das ist eine faire Frist.“\n\n[Chorus]\n„Ich verstehe Ihren Ärger, das tut mir wirklich leid,\nich kümmere mich persönlich drum – es dauert keine Ewigkeit.\nIhr Anliegen ist uns wichtig, wir finden einen Weg,\ndamit Ihre Zufriedenheit wieder an erster Stelle steht.“\n\n[Verse 3]\n„Ich würde Ihnen Folgendes vorschlagen: Die Lieferung erfolgt am Mittwoch früh,\ndie Versandkosten werden erstattet – für Ihre Geduld und Ihre Müh’.\nUnd Sie bekommen einen Gutschein, nicht nur als Entschuldigung, sondern auch als Dank,\nweil Sie uns treu geblieben sind, obwohl Sie warten mussten – viel zu lang.“\n\n[Bridge]\n„Na gut“, sagt sie, „das klingt fair, ich bin einverstanden.“\n„Wir danken Ihnen – schön, dass wir gemeinsam eine Lösung fanden.“\nAm Mittwoch um acht klingelt es – die Maschine ist da,\nund die Kundin lacht: „Na also, geht doch – wunderbar!“", "vocab": [["sich beschweren (über + Akk.)", "deutlich sagen, dass man mit etwas unzufrieden ist"], ["abbuchen", "Geld automatisch vom Konto nehmen"], ["die Warteschleife, die Warteschleifen", "am Telefon: Man wartet mit Musik, bis jemand antwortet"], ["die Zumutung, die Zumutungen", "etwas, das man nicht akzeptieren kann, weil es zu viel verlangt"], ["mit Verlaub (geh.)", "höfliche Einleitung vor einer offenen, kritischen Aussage"], ["das Anliegen, die Anliegen", "Wunsch, Bitte oder Problem, das man vorbringt"], ["sich kümmern um (+ Akk.)", "für eine Sache sorgen, sie erledigen"], ["stornieren", "einen Auftrag oder eine Buchung rückgängig machen"], ["erstatten", "Geld zurückzahlen"], ["die Versandkosten (Pl.)", "Kosten für das Verschicken einer Ware"], ["der Gutschein, die Gutscheine", "Papier oder Code mit einem Geldwert für einen späteren Einkauf"], ["einverstanden sein", "zustimmen, etwas akzeptieren"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["geliefert wurde nichts – doch ___ wurde mein Geld!", "in Ihrer ___ hing ich stundenlang – und das oft.", "Entweder kommt die Maschine bis Freitag, oder der Kauf wird ___!", "Ich wäre Ihnen ___, wenn das schnell geklärt würde – das ist eine faire Frist.“", "die Versandkosten werden ___ – für Ihre Geduld und Ihre Müh’."], "solutions": ["abgebucht", "Warteschleife", "storniert", "dankbar", "erstattet"]}, "suno": "bbdcc6c2-b283-464e-8d0c-35740db927ea"}, {"id": "b2-03-immer-online", "level": "B2", "title": "Immer online", "theme": "Digitalisierung: Arbeit, Alltag, ständige Erreichbarkeit, digitale Pausen", "grammar": "Nominalisierung (das Erreichen, die Abschaltung, die Erreichbarkeit); Redemittel Meinung (Meiner Meinung nach …, Ich bin der Ansicht, dass …); einerseits … andererseits", "intro": "Verbunden mit der ganzen Welt – und trotzdem allein? Dieser Synthwave-Song denkt über die Digitalisierung nach. Du übst Nominalisierungen und Redemittel, um deine Meinung zu sagen.", "lyrics": "[Verse 1]\nMein Wecker ist ein Handy, mein Gedächtnis eine Cloud,\nmeine Uhr zählt jeden Schritt – ich habe ihr blind vertraut.\nDie Digitalisierung der Arbeit kam schneller als gedacht:\nVideokonferenzen am Morgen, E-Mails bis in die Nacht.\n\n[Pre-Chorus]\nDas Erreichen aller Ziele, das Optimieren jeder Zeit,\ndas Vernetzen aller Dinge – sind wir dafür bereit?\n\n[Chorus]\nIch bin online, immer online,\nverbunden mit der ganzen Welt – und trotzdem allein.\nZwischen Fortschritt und Überforderung\nsuche ich die Balance, eine neue Ordnung.\n\n[Verse 2]\nEinerseits ist vieles leichter: ein Klick, ein Formular,\ndie Arbeit von zu Hause aus – für viele ein Gewinn, ganz klar.\nAndererseits raubt mir die ständige Erreichbarkeit\nden Schlaf, die Konzentration und ein großes Stück Freiheit.\n\n[Chorus]\nIch bin online, immer online,\nverbunden mit der ganzen Welt – und trotzdem allein.\nZwischen Fortschritt und Überforderung\nsuche ich die Balance, eine neue Ordnung.\n\n[Verse 3]\nMeiner Meinung nach liegt das Problem nicht in der Technik selbst,\nsondern darin, ob du die Kontrolle in den Händen hältst.\nIch bin der Ansicht, dass wir Grenzen ziehen müssen, klar und fest:\neine Stunde ohne Bildschirm – ein kleines digitales Fest.\n\n[Bridge]\nDie Abschaltung der Geräte um zehn,\ndas Lesen von Büchern, das Spazierengehen ohne Ziel – wie schön.\nDas Zuhören, das Schweigen, das Sehen –\nmanchmal muss man offline gehen.\n\n[Chorus]\nIch bin online, immer online,\nverbunden mit der ganzen Welt – und trotzdem allein.\nZwischen Fortschritt und Überforderung\nsuche ich die Balance, eine neue Ordnung.\n\n[Outro]\nOffline … nur für einen Moment.", "vocab": [["die Digitalisierung", "Umstellung von analogen auf digitale Prozesse und Technologien"], ["die Cloud, die Clouds", "Speicherplatz für Daten im Internet"], ["blind vertrauen", "jemandem ohne Kontrolle oder Zweifel glauben"], ["die Videokonferenz, die Videokonferenzen", "Besprechung über Kamera und Internet"], ["vernetzen", "Geräte oder Menschen miteinander verbinden"], ["der Fortschritt, die Fortschritte", "Entwicklung zu etwas Besserem oder Modernerem"], ["die Überforderung", "Zustand, wenn Aufgaben zu viel oder zu schwer sind"], ["die ständige Erreichbarkeit", "immer per Handy oder Mail kontaktierbar sein"], ["rauben", "hier: wegnehmen"], ["Grenzen ziehen", "klar festlegen, was man nicht mehr tun oder akzeptieren will"], ["der Bildschirm, die Bildschirme", "Monitor oder Display von Handy, Laptop oder Fernseher"], ["einerseits … andererseits", "Konnektor: zeigt zwei Seiten einer Sache"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Die ___ der Arbeit kam schneller als gedacht:", "Zwischen Fortschritt und ___", "Andererseits raubt mir die ständige ___", "sondern darin, ob du die ___ in den Händen hältst.", "Ich bin der Ansicht, dass wir ___ ziehen müssen, klar und fest:"], "solutions": ["Digitalisierung", "Überforderung", "Erreichbarkeit", "Kontrolle", "Grenzen"]}, "suno": "44c8d365-d480-467a-86e4-64c6db5b7833"}, {"id": "b2-04-feierabend", "level": "B2", "title": "Feierabend", "theme": "Work-Life-Balance: Überstunden, Erholung, Grenzen setzen, Gespräch mit der Chefin", "grammar": "Zweiteilige Konnektoren (zwar … aber, sowohl … als auch, je … desto, weder … noch, nicht nur … sondern auch, entweder … oder)", "intro": "Laptop zu, Feierabend! Dieser entspannte Reggae-Song erzählt, wie man aus dem Hamsterrad aussteigt – und trainiert ganz nebenbei alle wichtigen zweiteiligen Konnektoren.", "lyrics": "[Verse 1]\nZwar liebe ich meinen Job, aber nicht um jeden Preis,\nich drehe mich wie ein Hamster im ewigen Kreis.\nIch arbeite sowohl am Tag als auch oft in der Nacht\nund habe seit Wochen nicht mehr richtig gelacht.\n\n[Pre-Chorus]\nJe mehr ich mache, desto mehr kommt dazu,\nje länger ich bleibe, desto weniger finde ich Ruh’.\n\n[Chorus]\nFeierabend, Feierabend – der Laptop geht zu,\ndie Welt kann warten, jetzt bin ich dran – und du.\nWeder Mails noch Anrufe nach sechs Uhr,\nnur Sonne, Musik und ein Spaziergang durch die Natur.\n\n[Verse 2]\nMein Kollege sagt: „Wer früh geht, kommt nicht weit.“\nIch sage: „Wer nie Pause macht, brennt aus mit der Zeit.“\nNicht nur mein Körper braucht Erholung, sondern auch mein Kopf,\nsonst kocht der Druck irgendwann über wie Wasser im Topf.\n\n[Chorus]\nFeierabend, Feierabend – der Laptop geht zu,\ndie Welt kann warten, jetzt bin ich dran – und du.\nWeder Mails noch Anrufe nach sechs Uhr,\nnur Sonne, Musik und ein Spaziergang durch die Natur.\n\n[Verse 3]\nEntweder ich ändere was, oder es ändert sich nie,\nalso plane ich jetzt Pausen – mit Strategie.\nIch habe mit meiner Chefin gesprochen, ehrlich und direkt,\nund sie hat gesagt: „Danke, dass Sie das ansprechen – wir haben das zu spät entdeckt.“\n\n[Bridge]\nMittwochs Homeoffice, freitags früher Schluss,\nkein schlechtes Gewissen, kein Stress, kein Muss.\nJe ruhiger ich bin, desto besser arbeite ich auch –\ndas ist kein Luxus, das ist, was ich brauch’.\n\n[Outro]\nFeierabend … jetzt bin ich dran.", "vocab": [["der Feierabend", "Ende des Arbeitstages; die freie Zeit danach"], ["um jeden Preis", "egal, was es kostet; unbedingt"], ["sich im Kreis drehen", "immer dasselbe tun, ohne weiterzukommen"], ["die Erholung", "Ruhe und Pause, damit man wieder Kraft hat"], ["ausbrennen", "durch zu viel Stress völlig erschöpft werden (Burnout)"], ["der Druck", "hier: Stress, Belastung durch Erwartungen"], ["etwas ansprechen", "ein Thema offen zur Sprache bringen"], ["das schlechte Gewissen", "Gefühl, etwas falsch gemacht zu haben"], ["der Luxus", "etwas Besonderes, das man nicht unbedingt braucht"], ["zwar … aber", "Konnektor: Einschränkung oder Gegensatz"], ["je … desto", "Konnektor: Wenn sich das eine verändert, verändert sich auch das andere."], ["weder … noch", "Konnektor: nicht das eine und auch nicht das andere"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Zwar liebe ich meinen Job, aber nicht um jeden ___,", "Je mehr ich mache, ___ mehr kommt dazu,", "Weder Mails ___ Anrufe nach sechs Uhr,", "Nicht nur mein Körper braucht ___, sondern auch mein Kopf,", "kein schlechtes ___, kein Stress, kein Muss."], "solutions": ["Preis", "desto", "noch", "Erholung", "Gewissen"]}, "suno": "e63b841b-2ff3-4ec5-ad8a-952b5cc8e96e"}, {"id": "b2-05-nachtschicht", "level": "B2", "title": "Nachtschicht", "theme": "Gesundheit im Beruf: Schichtarbeit, Rücken, Erschöpfung, Arbeitsschutz, Teamzusammenhalt", "grammar": "Finalsätze (um … zu, damit) und Konsekutivsätze (so … dass, sodass); ohne … zu", "intro": "Wer andere pflegt, muss auch auf sich selbst achten. Dieser Soul-Song über eine Nachtschicht im Krankenhaus trainiert Sätze mit um … zu, damit und sodass.", "lyrics": "[Verse 1]\nNachtschicht im Krankenhaus, die Flure sind leer,\nmein Rücken tut weh, meine Beine sind schwer.\nIch hebe, ich trage, ich laufe die ganze Nacht\nund habe so oft nicht an mich selbst gedacht.\n\n[Pre-Chorus]\nIch war so müde, dass ich auf dem Heimweg am Steuer fast einschlief –\nda wusste ich: So geht es nicht weiter, irgendwas läuft schief.\n\n[Chorus]\nIch muss auf mich achten, um für andere da zu sein,\nich kann nicht alle retten – und schon gar nicht allein.\nIch brauche Pausen, damit ich wieder lachen kann –\nauch wer andere pflegt, ist selbst irgendwann dran.\n\n[Verse 2]\nDie Betriebsärztin hat gesagt: „So kann es nicht weitergehen.\nSie heben falsch, Sie schlafen zu wenig – das kann ich sehen.\nNutzen Sie die Hebehilfe, um den Rücken zu schonen,\nund gönnen Sie sich Ruhe – das wird sich lohnen.“\n\n[Chorus]\nIch muss auf mich achten, um für andere da zu sein,\nich kann nicht alle retten – und schon gar nicht allein.\nIch brauche Pausen, damit ich wieder lachen kann –\nauch wer andere pflegt, ist selbst irgendwann dran.\n\n[Verse 3]\nWir haben im Team besprochen, wie wir uns gegenseitig stützen\nund wie wir unsere Pausen in Zukunft besser schützen.\nKeiner springt mehr ein, ohne zu fragen, ob es geht,\nsodass nicht mehr nur einer bis zum Umfallen am Bett steht.\n\n[Bridge]\nErschöpfung ist kein Zeichen von Stärke,\nund Schlafmangel ist kein Beweis für gute Werke.\nWer dauerhaft über seine Grenzen geht,\nmerkt oft erst zu spät, was auf dem Spiel steht.\n\n[Outro]\nUm für andere da zu sein,\nmuss ich auf mich achten.", "vocab": [["die Nachtschicht, die Nachtschichten", "Arbeitszeit in der Nacht, z. B. von 21 bis 6 Uhr"], ["etwas läuft schief (ugs.)", "etwas funktioniert nicht so, wie es sollte"], ["auf sich achten", "gut für die eigene Gesundheit sorgen"], ["pflegen", "kranke oder alte Menschen betreuen und versorgen"], ["die Betriebsärztin, die Betriebsärztinnen", "Ärztin, die sich um die Gesundheit der Beschäftigten eines Unternehmens kümmert"], ["die Hebehilfe, die Hebehilfen", "Gerät, mit dem man Patienten ohne große Kraft bewegt"], ["schonen", "vorsichtig behandeln, nicht belasten"], ["sich etwas gönnen", "sich bewusst etwas Gutes erlauben"], ["einspringen", "kurzfristig für eine Kollegin oder einen Kollegen arbeiten"], ["bis zum Umfallen (ugs.)", "bis man vor Erschöpfung nicht mehr kann"], ["die Erschöpfung", "Zustand völliger Müdigkeit und Kraftlosigkeit"], ["auf dem Spiel stehen", "in Gefahr sein, verloren zu gehen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["mein ___ tut weh, meine Beine sind schwer.", "Ich muss auf mich ___, um für andere da zu sein,", "Nutzen Sie die Hebehilfe, um den Rücken zu ___,", "Keiner ___ mehr ein, ohne zu fragen, ob es geht,", "___ ist kein Zeichen von Stärke,"], "solutions": ["Rücken", "achten", "schonen", "springt", "Erschöpfung"]}, "suno": "c8fb898d-da1a-4035-b120-61c7e328a384"}, {"id": "b2-06-die-probezeit", "level": "B2", "title": "Die Probezeit", "theme": "Neu im Job: Einarbeitung, Feedback, Verantwortung", "grammar": "Nomen-Verb-Verbindungen (Verantwortung übernehmen, Kritik üben, eine Entscheidung treffen, in Anspruch nehmen)", "intro": "Sechs Monate Probezeit: neue Kollegen, neue Aufgaben, das erste Feedbackgespräch. Dieser Song begleitet dich durch die ersten Monate im Job – mit vielen Nomen-Verb-Verbindungen aus der Prüfung DTB B2.", "lyrics": "[Verse 1]\nErster Tag, neuer Ausweis, ein Schreibtisch am Fenster,\nzwanzig neue Namen, Passwörter wie Gespenster.\nMeine Mentorin sagt: „Du kannst jederzeit Fragen stellen,\nnimm dir Zeit, um dich mit allen in Verbindung zu setzen.“\n\n[Chorus]\nDas ist meine Probezeit – ich zeige, was in mir steckt,\nich übernehme Verantwortung, bevor mich die Angst erschreckt.\nIch treffe Entscheidungen, ich bringe Ideen zur Sprache –\ndas ist meine Probezeit, und das ist meine Sache.\n\n[Verse 2]\nIm dritten Monat übe ich zum ersten Mal Kritik,\nam Ablauf im Lager – ganz sachlich, mit Taktik.\nMein Chef nimmt Stellung, er hört mir lange zu:\n„Gute Idee – wir nehmen das gleich in Angriff, du und ich, im Nu.“\n\n[Chorus]\nDas ist meine Probezeit – ich zeige, was in mir steckt,\nich übernehme Verantwortung, bevor mich die Angst erschreckt.\nIch treffe Entscheidungen, ich bringe Ideen zur Sprache –\ndas ist meine Probezeit, und das ist meine Sache.\n\n[Bridge]\nIch nehme Hilfe in Anspruch, wenn ich nicht weiterweiß,\nich lege Wert auf Ehrlichkeit – das hat seinen Preis.\nSechs Monate vorbei – die Chefin gibt mir die Hand:\n„Sie haben einen großen Beitrag geleistet. Willkommen im Team, unbefristet!“\n\n[Chorus]\nDas ist meine Probezeit – ich zeige, was in mir steckt,\nich übernehme Verantwortung, bevor mich die Angst erschreckt.\nIch treffe Entscheidungen, ich bringe Ideen zur Sprache –\ndas ist meine Probezeit, und das ist meine Sache.", "vocab": [["die Probezeit", "die ersten Monate im Job; in dieser Zeit kann man leichter kündigen"], ["die Einarbeitung", "Zeit, in der man die neue Arbeit lernt"], ["die Mentorin, die Mentorinnen", "erfahrene Kollegin, die Neue begleitet"], ["sich in Verbindung setzen mit", "Kontakt aufnehmen"], ["Verantwortung übernehmen", "für etwas verantwortlich sein wollen"], ["eine Entscheidung treffen", "entscheiden"], ["zur Sprache bringen", "ein Thema ansprechen"], ["Kritik üben an", "etwas kritisieren"], ["Stellung nehmen", "seine Meinung zu etwas sagen"], ["in Angriff nehmen", "mit einer Aufgabe anfangen"], ["in Anspruch nehmen", "ein Angebot nutzen, z. B. Hilfe"], ["unbefristet", "ohne Enddatum (Arbeitsvertrag)"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Meine Mentorin sagt: „Du kannst jederzeit Fragen ___,", "ich übernehme ___, bevor mich die Angst erschreckt.", "Im dritten Monat übe ich zum ersten Mal ___,", "Mein Chef nimmt ___, er hört mir lange zu:", "Ich nehme Hilfe in ___, wenn ich nicht weiterweiß,"], "solutions": ["stellen", "Verantwortung", "Kritik", "Stellung", "Anspruch"]}, "suno": "13c56584-365c-4c1c-bcc6-f97ffbf73f84"}, {"id": "b2-07-was-wird-aus-uns", "level": "B2", "title": "Was wird aus uns?", "theme": "Arbeitswelt der Zukunft: künstliche Intelligenz, Automatisierung, Weiterbildung", "grammar": "Futur I für Vorhersagen und Vermutungen (wird … sein, wird wohl …); Futur II (wird … gemacht haben)", "intro": "Roboter im Lager, KI im Büro – was wird aus unseren Berufen? Dieser nachdenkliche Song blickt nach vorn und übt das Futur für Vorhersagen und Vermutungen.", "lyrics": "[Verse 1]\nIn zehn Jahren wird die Halle leiser sein,\nRoboter werden packen, Tag und Nacht, ganz allein.\nDie Software wird Berichte schreiben, schneller als wir,\nund ich frag mich leise: Wer sitzt dann noch hier?\n\n[Chorus]\nWas wird aus uns? Was wird aus mir?\nWir werden lernen, wir werden wachsen – das versprech ich dir.\nMaschinen werden rechnen, doch sie werden nicht verstehen,\nwie es sich anfühlt, gemeinsam weiterzugehen.\n\n[Verse 2]\nMeine Kollegin sagt: „Das wird wohl nicht so schlimm,\nneue Berufe werden kommen – das hat seinen Sinn.“\nSie wird wohl recht haben, sie hat oft den Blick,\nich melde mich zur Weiterbildung – es gibt kein Zurück.\n\n[Chorus]\nWas wird aus uns? Was wird aus mir?\nWir werden lernen, wir werden wachsen – das versprech ich dir.\nMaschinen werden rechnen, doch sie werden nicht verstehen,\nwie es sich anfühlt, gemeinsam weiterzugehen.\n\n[Bridge]\nIm Jahr zweitausendvierzig werden wir zurückschauen:\nWir werden vieles verändert haben – mit Mut und mit Vertrauen.\nDie Angst wird verschwunden sein, die Fragen bleiben jung –\nwas wird aus uns? Wir sind der Schwung.\n\n[Chorus]\nWas wird aus uns? Was wird aus mir?\nWir werden lernen, wir werden wachsen – das versprech ich dir.\nMaschinen werden rechnen, doch sie werden nicht verstehen,\nwie es sich anfühlt, gemeinsam weiterzugehen.", "vocab": [["die künstliche Intelligenz (KI)", "Computerprogramme, die selbst lernen und Aufgaben lösen"], ["die Automatisierung", "Maschinen übernehmen Arbeit von Menschen"], ["der Roboter, die Roboter", "Maschine, die Arbeiten automatisch macht"], ["die Halle, die Hallen", "großer Raum, z. B. im Lager oder in der Fabrik"], ["der Bericht, die Berichte", "Text mit Informationen über ein Thema"], ["rechnen", "mit Zahlen arbeiten"], ["die Weiterbildung, die Weiterbildungen", "Kurs, um im Beruf Neues zu lernen"], ["sich melden zu", "sich anmelden"], ["den Blick haben (für)", "etwas gut erkennen, einschätzen können"], ["verändern", "anders machen"], ["das Vertrauen", "der Glaube, dass etwas gut wird oder jemand ehrlich ist"], ["verschwinden", "nicht mehr da sein"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["In zehn Jahren wird die Halle ___ sein,", "Die ___ wird Berichte schreiben, schneller als wir,", "Maschinen werden ___, doch sie werden nicht verstehen,", "ich melde mich zur ___ – es gibt kein Zurück.", "Die Angst wird ___ sein, die Fragen bleiben jung –"], "solutions": ["leiser", "Software", "rechnen", "Weiterbildung", "verschwunden"]}, "suno": "ae3f2989-09b4-4168-87f5-8a90bebc2ecd"}, {"id": "b2-08-ich-sehe-das-anders", "level": "B2", "title": "Ich sehe das anders", "theme": "Diskussion im Team: Meinung, Widerspruch, Kompromiss", "grammar": "Redemittel für die Diskussion (zustimmen, widersprechen, Kompromiss); Konzessivsätze (obwohl, trotzdem, zwar … aber)", "intro": "Vier-Tage-Woche ja oder nein? Im Meeting prallen Meinungen aufeinander – und am Ende steht ein Kompromiss. Perfekt für die mündliche Prüfung im DTB B2.", "lyrics": "[Verse 1]\nMontagmorgen, Meeting, das Thema liegt im Raum:\n„Eine Vier-Tage-Woche – ist das Wirklichkeit oder Traum?“\nMeiner Ansicht nach wäre das ein großer Gewinn,\nzwar wird es schwierig, aber ich sehe einen Sinn.\n\n[Chorus]\nIch sehe das anders – und du siehst es auch nicht wie ich,\ntrotzdem hören wir zu, das ist wichtig für mich.\nWir sind zwar nicht einer Meinung, aber wir sprechen,\nwir finden einen Weg, ohne Brücken zu brechen.\n\n[Verse 2]\nMein Kollege sagt: „Da bin ich anderer Meinung,\nwer arbeitet am Freitag? Das ist keine Lösung.“\nDie Chefin nickt: „Da haben Sie nicht ganz unrecht,\nobwohl die Idee gut ist, passt sie für die Kunden schlecht.“\n\n[Chorus]\nIch sehe das anders – und du siehst es auch nicht wie ich,\ntrotzdem hören wir zu, das ist wichtig für mich.\nWir sind zwar nicht einer Meinung, aber wir sprechen,\nwir finden einen Weg, ohne Brücken zu brechen.\n\n[Bridge]\nWie wäre es, wenn wir es ein halbes Jahr probieren?\nIm Wechsel, im Team – dann kann niemand verlieren.\n„Damit wäre ich einverstanden“, sagt er und lacht,\nwir halten also fest: Ein Kompromiss ist gemacht.\n\n[Chorus]\nIch sehe das anders – und du siehst es auch nicht wie ich,\ntrotzdem hören wir zu, das ist wichtig für mich.\nWir sind zwar nicht einer Meinung, aber wir sprechen,\nwir finden einen Weg, ohne Brücken zu brechen.", "vocab": [["die Vier-Tage-Woche", "Arbeitsmodell mit vier statt fünf Arbeitstagen"], ["meiner Ansicht nach", "Redemittel: meine Meinung äußern"], ["der Gewinn", "hier: Vorteil, etwas Positives"], ["Da bin ich anderer Meinung.", "Redemittel: widersprechen"], ["Da haben Sie nicht ganz unrecht.", "Redemittel: teilweise zustimmen"], ["einer Meinung sein", "dasselbe denken"], ["nicken", "den Kopf auf und ab bewegen (= ja)"], ["Wie wäre es, wenn …?", "Redemittel: einen Vorschlag machen"], ["im Wechsel", "abwechselnd, mal der eine, mal der andere"], ["einverstanden sein mit", "zustimmen, etwas akzeptieren"], ["festhalten", "hier: zusammenfassen, notieren"], ["der Kompromiss, die Kompromisse", "Lösung, bei der beide Seiten etwas nachgeben"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Meiner ___ nach wäre das ein großer Gewinn,", "Mein Kollege sagt: „Da bin ich anderer ___,", "obwohl die Idee gut ist, passt sie für die ___ schlecht.“", "Wie wäre es, wenn wir es ein halbes ___ probieren?", "wir halten also fest: Ein ___ ist gemacht."], "solutions": ["Ansicht", "Meinung", "Kunden", "Jahr", "Kompromiss"]}, "suno": "39bbc327-f3fb-420d-a1f5-dc241fe946bd"}, {"id": "b2-09-der-letzte-zug", "level": "B2", "title": "Sobald der letzte Zug kommt", "theme": "Pendeln: lange Arbeitswege, Nahverkehr bei Nacht, Verspätungen, Zeit für sich", "grammar": "Temporale Nebensätze auf B2-Niveau (seitdem, während, solange, sobald, bevor, bis)", "intro": "Schicht vorbei, Bahnsteig im Regen, zehn Minuten Verspätung – dieser Song nimmt dich mit auf den langen Weg nach Hause. Du übst temporale Nebensätze mit seitdem, während, solange, sobald, bevor und bis.", "lyrics": "[Verse 1]\nDie Schicht ist vorbei, der Bahnsteig glänzt nass im Licht,\ndie Anzeige blinkt: „Zehn Minuten später“ – mehr sagt sie nicht.\nSeitdem ich in Dortmund arbeite und in Essen wohne,\nkenne ich jede Station, jede Durchsage, jede Zone.\nWährend die Stadt schon schläft, stehe ich hier und warte,\nin der Hand einen Kaffee, in der Tasche die Monatskarte.\n\n[Chorus]\nSobald der letzte Zug kommt, fahr ich nach Haus,\nsolange die Lichter brennen, halte ich das aus.\nBevor der Tag beginnt, bin ich zurück bei dir –\nbis der letzte Zug kommt, wartet die Nacht mit mir.\n\n[Verse 2]\nWährend der Zug durch die Nacht nach Westen rollt,\nschreibe ich dir: „Bin bald da“ – mehr habe ich nie gewollt.\nSolange mein Akku hält, höre ich deine Sprachnachricht,\ndeine Stimme im Kopfhörer – wie ein kleines, warmes Licht.\nBevor ich aussteige, lege ich die Stirn an die Scheibe,\nich sehe unser Fenster – und weiß, warum ich bleibe.\n\n[Chorus]\nSobald der letzte Zug kommt, fahr ich nach Haus,\nsolange die Lichter brennen, halte ich das aus.\nBevor der Tag beginnt, bin ich zurück bei dir –\nbis der letzte Zug kommt, wartet die Nacht mit mir.\n\n[Bridge]\nBis ich näher an der Arbeit wohne, ist der Zug mein Zuhause,\nzwischen Abfahrt und Ankunft liegt meine kleine Pause.\nSeitdem ich das so sehe, ist der Weg nicht mehr so schwer –\ndie Nacht fährt mit mir mit, und allein bin ich nicht mehr.\n\n[Chorus]\nSobald der letzte Zug kommt, fahr ich nach Haus,\nsolange die Lichter brennen, halte ich das aus.\nBevor der Tag beginnt, bin ich zurück bei dir –\nbis der letzte Zug kommt, wartet die Nacht mit mir.\n\n[Outro]\nSobald der letzte Zug kommt …\nfahr ich nach Haus.\nBis dahin wartet die Nacht mit mir.", "vocab": [["pendeln", "regelmäßig zwischen Wohnort und Arbeitsort hin- und herfahren"], ["die Schicht, die Schichten", "feste Arbeitszeit, z. B. Früh-, Spät- oder Nachtschicht"], ["der Bahnsteig, die Bahnsteige", "Ort am Gleis, an dem man ein- und aussteigt"], ["die Anzeige, die Anzeigen", "Bildschirm mit Informationen, z. B. zu Abfahrt und Verspätung"], ["die Durchsage, die Durchsagen", "Information über den Lautsprecher"], ["die Monatskarte, die Monatskarten", "Fahrkarte, die einen Monat lang gilt"], ["etwas aushalten", "etwas Schweres ertragen, nicht aufgeben"], ["der Akku, die Akkus", "Batterie im Handy, die man aufladen kann"], ["die Sprachnachricht, die Sprachnachrichten", "gesprochene Nachricht im Messenger"], ["die Ankunft, die Ankünfte", "der Moment, in dem man an einem Ort ankommt"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["die ___ blinkt: „Zehn Minuten später“ – mehr sagt sie nicht.", "___ ich in Dortmund arbeite und in Essen wohne,", "in der Hand einen Kaffee, in der Tasche die ___.", "___ mein Akku hält, höre ich deine Sprachnachricht,", "Bis ich näher an der Arbeit wohne, ist der Zug mein ___,"], "solutions": ["Anzeige", "Seitdem", "Monatskarte", "Solange", "Zuhause"]}, "suno": "bbd6bf59-6380-477f-ab90-64d6079e5d5e"}, {"id": "b2-10-das-fenster-gegenueber", "level": "B2", "title": "Das Fenster gegenüber", "theme": "Neu in der Großstadt: Anonymität, Einsamkeit, neue Kontakte und Freundschaft", "grammar": "Relativsätze auf B2-Niveau: Relativpronomen im Genitiv (dessen, deren), was und wo(r)- nach alles/das Beste (alles, was / alles, wonach), Relativsätze mit wo und wer", "intro": "Neue Stadt, viele Menschen – und trotzdem kennt niemand deinen Namen. Dieser nächtliche Song erzählt von einem Licht im Fenster gegenüber und trainiert Relativsätze mit deren, dessen, was, wo und wer.", "lyrics": "[Verse 1]\nSeit März wohne ich im vierten Stock, im Hinterhaus,\ndie Nachbarn, deren Namen ich nicht kenne, sehen müde und eilig aus.\nDort, wo ich herkomme, grüßt man sich auf jeder Treppe –\nhier höre ich nur meine Schritte, wenn ich die Einkäufe schleppe.\nNur gegenüber, wo die alte Kastanie steht,\nbrennt jede Nacht ein Licht, das erst am Morgen ausgeht.\n\n[Chorus]\nIn der Stadt, in der niemand meinen Namen kennt,\nbist du das Fenster, in dem noch Licht brennt.\nDu bist alles, wonach ich suche, wenn es regnet –\ndas Beste, was mir hier begegnet.\n\n[Verse 2]\nEines Nachts im Kiosk, wo es noch warmen Kaffee gab,\nstand sie vor mir – die Frau, deren Fenster ich jeden Abend sah.\nSie lachte: „Du bist der vom vierten Stock, der nachts nie schlafen kann.“\nWir tranken Kaffee im Regen – und so fing alles an.\nSie erzählte von der Arbeit, für die sie hergezogen war,\nvon Sonntagen, an denen das Telefon schwieg – ein ganzes Jahr.\n\n[Chorus]\nIn der Stadt, in der niemand meinen Namen kennt,\nbist du das Fenster, in dem noch Licht brennt.\nDu bist alles, wonach ich suche, wenn es regnet –\ndas Beste, was mir hier begegnet.\n\n[Bridge]\nWer neu in einer Stadt ist, sucht nach einem kleinen Blick,\nnach einem Hallo im Treppenhaus, nach einem Stück Glück.\nWer nachts allein ist, ist selten der Einzige, der wacht –\nirgendwo ist ein Fenster, hinter dem noch jemand lacht.\n\n[Chorus]\nIn der Stadt, in der niemand meinen Namen kennt,\nbist du das Fenster, in dem noch Licht brennt.\nDu bist alles, wonach ich suche, wenn es regnet –\ndas Beste, was mir hier begegnet.\n\n[Outro]\nDas Fenster gegenüber,\nin dem noch Licht brennt –\ndas Beste, was mir hier begegnet.", "vocab": [["das Hinterhaus, die Hinterhäuser", "Haus hinter einem anderen Haus, man geht durch den Hof"], ["grüßen", "„Hallo“ oder „Guten Tag“ sagen"], ["schleppen", "etwas Schweres mühsam tragen"], ["gegenüber", "auf der anderen Seite, z. B. der Straße"], ["die Kastanie, die Kastanien", "großer Baum mit braunen Früchten"], ["der Kiosk, die Kioske", "kleiner Laden, oft bis spät in die Nacht geöffnet"], ["herziehen (ist hergezogen)", "an diesen Ort umziehen"], ["schweigen", "nichts sagen, still sein"], ["begegnen (+ Dativ)", "jemanden zufällig treffen"], ["wachen", "nicht schlafen, wach bleiben"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["die Nachbarn, ___ Namen ich nicht kenne, sehen müde und eilig aus.", "Dort, wo ich herkomme, ___ man sich auf jeder Treppe –", "bist du das Fenster, in dem noch Licht ___.", "Sie erzählte von der Arbeit, für die sie ___ war,", "irgendwo ist ein Fenster, hinter dem noch jemand ___."], "solutions": ["deren", "grüßt", "brennt", "hergezogen", "lacht"]}, "suno": "f2022e0d-dcbd-4b78-833d-e34490738579"}, {"id": "c1-01-zwischen-den-zeilen", "level": "C1", "title": "Zwischen den Zeilen", "theme": "Sprache und Identität: Mehrsprachigkeit, Akzent, Zugehörigkeit", "grammar": "Erweiterte Partizipialattribute (die mühsam gelernten Regeln, ein langsam wachsender Garten)", "intro": "Wie fühlt es sich an, in einer Sprache zu leben, in der man nicht geboren ist? Dieses poetische Chanson spielt mit Bildern für Mehrsprachigkeit – und mit erweiterten Partizipialattributen.", "lyrics": "[Verse 1]\nIch trage eine Sprache, in der ich nicht geboren bin,\ndie mir geliehenen Wörter geben meinem Leben neuen Sinn.\nDie mühsam auswendig gelernten Regeln liegen schwer auf meiner Zunge,\ndoch jedes neu entdeckte Wort füllt mir wie Luft die Lunge.\n\n[Pre-Chorus]\nDer, die, das – ein nie endender Tanz,\ndoch ein falsch gesetzter Artikel nimmt mir nicht den Glanz.\n\n[Chorus]\nIch lebe zwischen den Zeilen, zwischen hier und dort,\nin jedem übersetzten Satz verliere ich ein Wort,\nund finde dafür ein neues, das nach Heimat klingt –\nein in zwei Sprachen geträumtes Lied, das in mir singt.\n\n[Verse 2]\nMeine Großmutter sprach in Bildern, die kein Wörterbuch kennt,\nein nie ganz erloschenes Feuer, das noch in mir brennt.\nMan lobt mich: „Sie sprechen ja fast ohne Akzent!“ –\nals wäre meine Herkunft ein Makel, den man zum Glück nicht mehr erkennt.\n\n[Chorus]\nIch lebe zwischen den Zeilen, zwischen hier und dort,\nin jedem übersetzten Satz verliere ich ein Wort,\nund finde dafür ein neues, das nach Heimat klingt –\nein in zwei Sprachen geträumtes Lied, das in mir singt.\n\n[Verse 3]\nIch will nicht aufgehen in einer glatt polierten Norm,\nmein Deutsch hat Ecken und Kanten – und gerade das gibt ihm Form.\nDie Sprache ist ein Haus mit vielen offenen Türen,\nin jedem darin verbrachten Jahr kann ich es tiefer spüren.\n\n[Bridge]\nSprache ist kein Pass, kein Stempel, kein Beweis,\nsie ist ein langsam wachsender Garten – und er wächst auf meine Weise.\nEin von vielen Stimmen getragenes Ich –\ndas bin ich, das bin ich.\n\n[Outro]\nZwischen den Zeilen … da wohne ich.", "vocab": [["mühsam", "mit viel Anstrengung und Geduld"], ["leihen (lieh, hat geliehen)", "etwas für eine Zeit geben, das später zurückkommen soll"], ["zwischen den Zeilen", "im nicht direkt Gesagten, in der versteckten Bedeutung"], ["erloschen", "nicht mehr brennend (Feuer, Licht); übertragen: vorbei"], ["der Akzent, die Akzente", "besondere Aussprache, an der man die Herkunft hört"], ["der Makel, die Makel", "Fehler oder Schwäche, die negativ auffällt"], ["die Herkunft", "Land, Familie oder Milieu, aus dem jemand stammt"], ["aufgehen in (+ Dat.)", "ganz Teil von etwas werden und sich darin verlieren"], ["die Norm, die Normen", "Regel, Standard, das als normal Geltende"], ["Ecken und Kanten haben", "nicht glatt und angepasst sein, Persönlichkeit zeigen"], ["der Glanz", "Leuchten; übertragen: Ausstrahlung, Würde"], ["der Beweis, die Beweise", "etwas, das zeigt, dass eine Behauptung stimmt"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["die mir ___ Wörter geben meinem Leben neuen Sinn.", "doch jedes neu ___ Wort füllt mir wie Luft die Lunge.", "in jedem ___ Satz verliere ich ein Wort,", "ein nie ganz ___ Feuer, das noch in mir brennt.", "mein Deutsch hat Ecken und ___ – und gerade das gibt ihm Form."], "solutions": ["geliehenen", "entdeckte", "übersetzten", "erloschenes", "Kanten"]}, "suno": "8d74b826-5bfd-440e-933b-976eec4dd73c"}, {"id": "c1-02-ungeschriebene-briefe", "level": "C1", "title": "Ungeschriebene Briefe", "theme": "Erinnerung: Großvater, Bergbau, Strukturwandel im Ruhrgebiet", "grammar": "Plusquamperfekt; Konjunktiv II der Vergangenheit (Hätte ich doch …, Er hätte … gekonnt, wenn …); temporale Nebensätze (nachdem, bevor, als)", "intro": "Ein leeres Zechenhaus, ein Großvater, viele unausgesprochene Fragen: Diese melancholische Piano-Ballade erzählt von Erinnerung und Strukturwandel im Ruhrgebiet. Du übst Plusquamperfekt und Konjunktiv II der Vergangenheit.", "lyrics": "[Verse 1]\nDas Haus in der Siedlung steht noch, die Fenster sind blind,\nim Garten, wo wir Bohnen zogen, spielt jetzt nur der Wind.\nHier hatte mein Großvater nach der Schicht im Schacht gesessen,\nden Kohlenstaub im Gesicht, und Brot mit Schmalz gegessen.\n\n[Verse 2]\nBevor er morgens losging, hatte er mir oft erzählt:\n„Unter Tage, Junge, ist das Licht das, was am meisten fehlt.“\nIch hatte nie verstanden, was in seinen Händen lag:\ndie Härte und die Zärtlichkeit, die Kraft für jeden Tag.\n\n[Chorus]\nHätte ich ihn doch öfter gefragt,\nwäre ich nur länger geblieben!\nErinnerung ist ein Haus mit vielen Zimmern –\nund manche Briefe bleiben ungeschrieben.\n\n[Verse 3]\nAls die Zeche schloss, war er gerade sechzig geworden,\nman gab ihm eine Urkunde – aber keinen neuen Morgen.\nEr hätte noch so viel gekonnt, hätte man ihn nur gelassen,\nstattdessen saß er abends schweigend vor den leeren Tassen.\n\n[Chorus]\nHätte ich ihn doch öfter gefragt,\nwäre ich nur länger geblieben!\nErinnerung ist ein Haus mit vielen Zimmern –\nund manche Briefe bleiben ungeschrieben.\n\n[Bridge]\nWo früher Kohle gefördert wurde, wird heute getanzt,\ndie Halden sind begrünt, und Birken sind gepflanzt.\nIch stehe oben auf der Halde, und ich höre seinen Schritt,\nder Wind trägt seine Stimme – und ich nehme sie mit.\n\n[Chorus]\nHätte ich ihn doch öfter gefragt,\nwäre ich nur länger geblieben!\nErinnerung ist ein Haus mit vielen Zimmern –\nund manche Briefe bleiben ungeschrieben.\n\n[Outro]\nManche Briefe bleiben ungeschrieben …\naber nicht vergessen.", "vocab": [["die Siedlung, die Siedlungen", "Gruppe ähnlicher Häuser, hier für Bergarbeiterfamilien"], ["die Schicht, die Schichten", "festgelegte Arbeitszeit, z. B. Früh- oder Nachtschicht"], ["der Schacht, die Schächte", "senkrechter Tunnel in die Tiefe eines Bergwerks"], ["unter Tage", "unter der Erde, im Bergwerk"], ["der Kohlenstaub", "feine schwarze Teilchen von Kohle"], ["die Zeche, die Zechen", "Bergwerk für Kohle (besonders im Ruhrgebiet)"], ["die Halde, die Halden", "künstlicher Berg aus Gestein vom Bergbau"], ["(Kohle) fördern", "aus der Erde holen, abbauen"], ["die Urkunde, die Urkunden", "offizielles Dokument, z. B. als Anerkennung"], ["die Zärtlichkeit", "liebevolle, sanfte Zuwendung"], ["Bohnen ziehen", "Bohnen im Garten anbauen"], ["ungeschrieben", "nie zu Papier gebracht"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Hier hatte mein Großvater nach der ___ im Schacht gesessen,", "„Unter Tage, Junge, ist das ___ das, was am meisten fehlt.“", "Ich hatte nie ___, was in seinen Händen lag:", "Hätte ich ihn doch ___ gefragt,", "Wo früher Kohle ___ wurde, wird heute getanzt,"], "solutions": ["Schicht", "Licht", "verstanden", "öfter", "gefördert"]}, "suno": "874925b3-692d-4486-b1ab-a2b0169e42b8"}, {"id": "c1-03-wandel-wird-gemacht", "level": "C1", "title": "Wandel wird gemacht", "theme": "Gesellschaft und Wandel: Strukturwandel, soziale Ungleichheit, Vielfalt, Engagement", "grammar": "Nominalstil; Präpositionen mit Genitiv (angesichts, infolge, trotz, aufgrund); Umformung Nebensatz ↔ Nominalgruppe", "intro": "Steigende Mieten, geschlossene Werke, große Versprechen: Dieser Conscious-Rap fragt, wer den Wandel eigentlich gestaltet. Du trainierst Nominalstil und Präpositionen mit Genitiv.", "lyrics": "[Verse 1]\nAngesichts steigender Mieten und sinkender Löhne\nfragt sich meine Nachbarin, ob sie sich je daran gewöhnt.\nInfolge der Schließung des Werkes vor zehn Jahren\nsind die Jungen weggezogen – geblieben sind die mit grauen Haaren.\nTrotz aller Versprechen von Wandel und Neubeginn\nfragen viele: Wo ist für uns darin der Sinn?\nAufgrund fehlender Busse, Ärzte, Läden um die Ecke\nbleibt manches Viertel im wahrsten Sinne auf der Strecke.\n\n[Chorus]\nAlles im Wandel, nichts bleibt, wie es war,\nwer nicht mitkommt, wird übersehen – Jahr für Jahr.\nDoch Wandel ist kein Schicksal, Wandel wird gemacht –\nvon Menschen, die sich einmischen, und zwar mit Bedacht.\n\n[Verse 2]\nDie Förderung von Bildung, die Stärkung der Bindung\nzwischen Alt und Jung – so steht’s in jeder Ankündigung.\nDoch zwischen der Planung und der Umsetzung liegen Jahre,\nin denen manche Idee verstaubt – und das ist nicht das Wahre.\nMeine Oma sagt: „Früher war nicht alles besser, Kind,\nnur langsamer – heute dreht sich alles so geschwind.“\n\n[Chorus]\nAlles im Wandel, nichts bleibt, wie es war,\nwer nicht mitkommt, wird übersehen – Jahr für Jahr.\nDoch Wandel ist kein Schicksal, Wandel wird gemacht –\nvon Menschen, die sich einmischen, und zwar mit Bedacht.\n\n[Verse 3]\nWir sind die Kinder von Gastarbeitern, Bergleuten, Geflüchteten,\ndie Enkel derer, die hier Häuser und Brücken errichteten.\nUnsere Vielfalt ist kein Problem, das gelöst werden muss,\nsondern eine Antwort – und zwar nicht erst zum Schluss.\n\n[Bridge]\nWas wir heute säen, wird morgen erst blühen,\nes lohnt sich, sich zu bemühen.\nEs lohnt sich, sich zu bemühen.\n\n[Chorus]\nAlles im Wandel, nichts bleibt, wie es war,\nwer nicht mitkommt, wird übersehen – Jahr für Jahr.\nDoch Wandel ist kein Schicksal, Wandel wird gemacht –\nvon Menschen, die sich einmischen, und zwar mit Bedacht.\n\n[Outro]\nWandel wird gemacht.", "vocab": [["angesichts (+ Gen.)", "im Hinblick auf; wenn man … betrachtet"], ["infolge (+ Gen.)", "als Folge von"], ["aufgrund (+ Gen.)", "wegen, verursacht durch"], ["auf der Strecke bleiben", "scheitern, nicht mitkommen, vergessen werden"], ["das Schicksal, die Schicksale", "Lauf des Lebens, der scheinbar vorherbestimmt ist"], ["sich einmischen", "aktiv Einfluss nehmen, sich beteiligen"], ["mit Bedacht", "überlegt, sorgfältig"], ["die Umsetzung, die Umsetzungen", "Verwirklichung eines Plans in der Praxis"], ["verstauben", "lange ungenutzt liegen bleiben"], ["nicht das Wahre sein (ugs.)", "nicht wirklich gut, nicht ideal sein"], ["die Vielfalt", "Verschiedenheit, große Zahl unterschiedlicher Formen"], ["errichten", "bauen, aufbauen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["___ steigender Mieten und sinkender Löhne", "Infolge der ___ des Werkes vor zehn Jahren", "bleibt manches Viertel im wahrsten Sinne auf der ___.", "Doch Wandel ist kein ___, Wandel wird gemacht –", "Unsere ___ ist kein Problem, das gelöst werden muss,"], "solutions": ["Angesichts", "Schließung", "Strecke", "Schicksal", "Vielfalt"]}, "suno": "1946ba08-31af-4d8e-abc5-201fd9fc48d2"}, {"id": "c1-04-ins-kalte-wasser", "level": "C1", "title": "Ins kalte Wasser", "theme": "Mut und Neuanfang: Jobverlust, Selbstständigkeit, Risiko, Durchhalten", "grammar": "Idiomatische Wendungen; irreale Vergleichssätze mit als ob / als + Konjunktiv II", "intro": "Mit vierzig alles hinwerfen und eine Bäckerei eröffnen? Dieser hymnische Indie-Rock-Song steckt voller Redewendungen – und zeigt, dass Mut nicht heißt, keine Angst zu haben.", "lyrics": "[Verse 1]\nIch stand mit dem Rücken zur Wand, der Job war weg, die Kasse leer,\nich tat, als ob mir das nichts ausmachte – doch das Lächeln fiel mir schwer.\nZehn Jahre im selben Büro, im selben Trott, im selben Grau,\nund tief in mir wusste ich es ganz genau.\n\n[Pre-Chorus]\nAlle sagten: „Bleib auf dem Teppich! Spiel nicht mit dem Feuer!\nEin Neuanfang mit vierzig? Das ist uns nicht geheuer!“\n\n[Chorus]\nIch springe ins kalte Wasser, ich wage den ersten Schritt –\nwer nie etwas riskiert, nimmt am Ende nichts vom Leben mit.\nEs ist, als würde ich nach langer Zeit wieder atmen,\nich setze alles auf eine Karte – und lasse die Angst draußen warten.\n\n[Verse 2]\nJetzt backe ich kleine Brötchen – und zwar im wörtlichen Sinn:\neine winzige Bäckerei im Viertel, und ich stehe mittendrin.\nUm vier Uhr früh der Wecker, Mehl in den Haaren, Teig an der Hand,\nso manches ging in die Hose – doch ich warf nie das Handtuch, ich hielt stand.\n\n[Chorus]\nIch springe ins kalte Wasser, ich wage den ersten Schritt –\nwer nie etwas riskiert, nimmt am Ende nichts vom Leben mit.\nEs ist, als würde ich nach langer Zeit wieder atmen,\nich setze alles auf eine Karte – und lasse die Angst draußen warten.\n\n[Verse 3]\nDie Nachbarn kamen zögernd, dann kamen sie in Scharen,\nals hätten sie auf so einen Laden gewartet – seit Jahren.\nIch bin nicht reich geworden, doch ich bin wieder ich,\nund das ist mehr wert als jedes Gehalt – zumindest für mich.\n\n[Bridge]\nMut heißt nicht, keine Angst zu haben,\nMut heißt, trotz zitternder Knie loszugehen – mit offenen Fragen.\nUnd wenn du fällst, dann fällst du – aber nicht ins Leere:\nDu landest, oder du lernst – und beides ist eine Lehre.", "vocab": [["mit dem Rücken zur Wand stehen", "in einer sehr schwierigen Lage sein, keinen Ausweg sehen"], ["der Trott", "eintöniger, immer gleicher Ablauf"], ["auf dem Teppich bleiben", "realistisch und bescheiden bleiben"], ["mit dem Feuer spielen", "ein gefährliches Risiko eingehen"], ["jemandem nicht geheuer sein", "jemandem unheimlich oder verdächtig vorkommen"], ["ins kalte Wasser springen", "etwas Neues ohne Vorbereitung beginnen"], ["alles auf eine Karte setzen", "alles für eine einzige Möglichkeit riskieren"], ["kleine Brötchen backen", "bescheiden sein, mit wenig zufrieden sein"], ["in die Hose gehen (ugs.)", "misslingen, schiefgehen"], ["das Handtuch werfen", "aufgeben"], ["standhalten (hielt stand)", "nicht nachgeben, durchhalten"], ["in Scharen", "in großer Zahl"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich stand mit dem Rücken zur ___, der Job war weg, die Kasse leer,", "Alle sagten: „Bleib auf dem ___! Spiel nicht mit dem Feuer!", "Ich springe ins kalte ___, ich wage den ersten Schritt –", "ich setze alles auf eine ___ – und lasse die Angst draußen warten.", "so manches ging in die Hose – doch ich warf nie das ___, ich hielt stand."], "solutions": ["Wand", "Teppich", "Wasser", "Karte", "Handtuch"]}, "suno": "ec35d526-3c46-4345-b94b-817ebd93de34"}, {"id": "c1-05-man-sagt", "level": "C1", "title": "Man sagt", "theme": "Medien und Wahrheit: Politik, Influencer, Schlagzeilen, Desinformation, Vertrauen", "grammar": "Konjunktiv I in der indirekten Rede (er habe, sie seien, es gebe); Redewiedergabe mit distanzierenden Verben (behaupten, schwören, warnen)", "intro": "Wer sagt was – und wer hat es bezahlt? Dieser düstere Trip-Hop-Song über Medien und Wahrheit ist fast komplett in indirekter Rede geschrieben. Perfekt, um den Konjunktiv I zu üben.", "lyrics": "[Verse 1]\nEin Minister sagt, er habe von all dem nichts gewusst,\ndie Aufregung sei ein Sturm im Wasserglas – man sei sich der Verantwortung bewusst.\nEine Sprecherin erklärt, die Zahlen seien korrekt,\nnichts werde vertuscht und nichts werde versteckt.\n\n[Pre-Chorus]\nEin Influencer schwört, sein Pulver mache jung und schlank,\nmit dem Code in seiner Bio gebe es Rabatt – na, vielen Dank!\n\n[Chorus]\nMan sagt, man hört, man liest, man teilt,\ndie Wahrheit hinkt hinterher, während die Lüge eilt.\nWer sagt was, warum – und wer hat es bezahlt?\nBevor du es glaubst, frag dich, wer da die Bilder malt.\n\n[Verse 2]\nDie Schlagzeile schreit, und der Artikel flüstert,\nder Kontext geht verloren, irgendwo im Feed, der leise knistert.\nEin aus dem Zusammenhang gerissenes Zitat\ngeht viral, bevor ein Mensch es überprüft hat.\n\n[Chorus]\nMan sagt, man hört, man liest, man teilt,\ndie Wahrheit hinkt hinterher, während die Lüge eilt.\nWer sagt was, warum – und wer hat es bezahlt?\nBevor du es glaubst, frag dich, wer da die Bilder malt.\n\n[Verse 3]\nDie Redaktion teilt mit, man habe den Fehler korrigiert,\ndoch die Korrektur wird kaum gelesen, kaum geteilt, kaum registriert.\nEin Experte warnt, Vertrauen sei ein knappes Gut:\nWer es verspiele, gewinne es nur langsam zurück – mit Zeit, Geduld und Mut.\n\n[Bridge]\nIch sage nicht, alles sei gelogen,\nich sage nur: Die Wahrheit ist oft ein wenig verbogen.\nPrüf die Quelle, lies weiter, zweifle mit Verstand –\ndas Urteil liegt am Ende in deiner eigenen Hand.\n\n[Chorus]\nMan sagt, man hört, man liest, man teilt,\ndie Wahrheit hinkt hinterher, während die Lüge eilt.\nWer sagt was, warum – und wer hat es bezahlt?\nBevor du es glaubst, frag dich, wer da die Bilder malt.\n\n[Outro]\nMan sagt … aber was sagst du?", "vocab": [["ein Sturm im Wasserglas", "große Aufregung über eine unwichtige Sache"], ["vertuschen", "etwas Negatives absichtlich verbergen"], ["schwören", "feierlich versichern, dass etwas wahr ist"], ["die Schlagzeile, die Schlagzeilen", "groß gedruckte Überschrift eines Artikels"], ["etwas aus dem Zusammenhang reißen", "einen Teil ohne seinen Kontext zitieren, sodass sich der Sinn verändert"], ["viral gehen", "sich sehr schnell im Internet verbreiten"], ["die Redaktion, die Redaktionen", "Team, das die Inhalte einer Zeitung oder eines Senders verantwortet"], ["ein knappes Gut", "etwas Wertvolles, von dem es nur wenig gibt"], ["verspielen", "durch eigenes Verhalten verlieren"], ["die Quelle, die Quellen", "Ursprung einer Information"], ["hinterherhinken", "langsamer sein als andere, zurückbleiben"], ["das Urteil, die Urteile", "abschließende Bewertung, Entscheidung"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Eine Sprecherin erklärt, die Zahlen ___ korrekt,", "die Wahrheit hinkt hinterher, während die ___ eilt.", "Ein aus dem Zusammenhang ___ Zitat", "Ein Experte warnt, Vertrauen sei ein ___ Gut:", "Prüf die ___, lies weiter, zweifle mit Verstand –"], "solutions": ["seien", "Lüge", "gerissenes", "knappes", "Quelle"]}, "suno": "18d78355-2a3f-444a-9499-f9d8f55f0feb"}, {"id": "c1-06-was-sich-nicht-messen-laesst", "level": "C1", "title": "Was sich nicht messen lässt", "theme": "Leistungsgesellschaft, Glück und Werte", "grammar": "Passiversatzformen (sich lassen + Infinitiv, sein + zu + Infinitiv, Adjektive auf -bar/-lich)", "intro": "Schritte, Klicks, Kennzahlen – alles wird gemessen. Aber was ist mit Freundschaft, Trost und Glück? Ein atmosphärischer Song über das Unmessbare, der Passiversatzformen trainiert.", "lyrics": "[Verse 1]\nMeine Uhr zählt jeden Schritt, mein Handy jeden Blick,\njede Leistung ist erfassbar, jede Stunde lässt sich zurück\nin Tabellen übersetzen, in Kurven, rot und grün –\ndoch was ich nachts empfinde, ist darin nicht zu sehen.\n\n[Chorus]\nWas sich nicht messen lässt, das trägt mich durch die Zeit,\nein Lächeln ist nicht zählbar, und Trost ist nicht zu kaufen, nirgends weit und breit.\nWas sich nicht messen lässt, ist unbezahlbar, still und klar –\ndas, was zählt, ist oft unzählbar.\n\n[Verse 2]\nDer Bericht ist bis Freitag einzureichen, das Ziel ist definiert,\ndie Zahlen lassen sich verbessern, alles wird optimiert.\nDoch die Stimme meiner Freundin, als sie sagte: „Ich bin da“,\nist mit keiner Formel zu berechnen – unbegreiflich nah.\n\n[Chorus]\nWas sich nicht messen lässt, das trägt mich durch die Zeit,\nein Lächeln ist nicht zählbar, und Trost ist nicht zu kaufen, nirgends weit und breit.\nWas sich nicht messen lässt, ist unbezahlbar, still und klar –\ndas, was zählt, ist oft unzählbar.\n\n[Bridge]\nVieles ist machbar, vieles ist planbar,\ndoch nicht alles ist erklärbar.\nLass die Zahlen ruhig fallen – sie lassen sich ersetzen.\nDie Momente nicht.\n\n[Chorus]\nWas sich nicht messen lässt, das trägt mich durch die Zeit,\nein Lächeln ist nicht zählbar, und Trost ist nicht zu kaufen, nirgends weit und breit.\nWas sich nicht messen lässt, ist unbezahlbar, still und klar –\ndas, was zählt, ist oft unzählbar.", "vocab": [["messen", "die Größe, Menge oder Zeit von etwas bestimmen"], ["die Leistung, die Leistungen", "was man erreicht oder schafft"], ["erfassbar", "so, dass man es erfassen (aufnehmen, registrieren) kann"], ["empfinden", "fühlen"], ["der Trost", "Hilfe und Wärme, wenn jemand traurig ist"], ["unbezahlbar", "so wertvoll, dass man es nicht kaufen kann"], ["unzählbar", "so viel oder so besonders, dass man es nicht zählen kann"], ["einreichen", "offiziell abgeben"], ["optimieren", "immer weiter verbessern"], ["berechnen", "mit Zahlen ausrechnen"], ["unbegreiflich", "so, dass man es nicht verstehen kann"], ["ersetzen", "durch etwas anderes austauschen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["jede Leistung ist ___, jede Stunde lässt sich zurück", "doch was ich nachts ___, ist darin nicht zu sehen.", "Was sich nicht messen lässt, ist ___, still und klar –", "Der Bericht ist bis Freitag ___, das Ziel ist definiert,", "doch nicht alles ist ___."], "solutions": ["erfassbar", "empfinde", "unbezahlbar", "einzureichen", "erklärbar"]}, "suno": "4f76df7f-b281-422d-b745-7e66c3b13c47"}, {"id": "c1-07-sie-soll-es-gewusst-haben", "level": "C1", "title": "Sie soll es gewusst haben", "theme": "Gerüchte am Arbeitsplatz, Vertrauen und Verantwortung", "grammar": "Modalverben in subjektiver Bedeutung (sollen und wollen für fremde/eigene Behauptungen, müssen/dürften/können für Vermutungen), auch im Infinitiv Perfekt", "intro": "In der Kaffeeküche wird geflüstert: Die Kollegin soll alles gewusst haben, der Chef will von nichts gewusst haben. Ein düsterer Song über Gerüchte – und über subjektive Modalverben.", "lyrics": "[Verse 1]\nIn der Kaffeeküche hängt ein Satz in der Luft,\nhalb geflüstert, halb gelacht, wie ein bitterer Duft:\n„Sie soll es gewusst haben, schon seit letztem Jahr,\nsie soll die Zahlen geschönt haben – jeder weiß, es ist wahr.“\n\n[Chorus]\nSie soll es gewusst haben – sagt man, sagt man so,\ner will von nichts gewusst haben – irgendwo, irgendwie, irgendwo.\nEs muss doch jemand wissen, es dürfte längst bekannt sein –\ndoch ein Gerücht ist schneller als die Wahrheit, und die Wahrheit bleibt allein.\n\n[Verse 2]\nDer Chef will nichts bemerkt haben, er war im Urlaub, sagt er nur,\ndie Akten können verschwunden sein, es fehlt von ihnen jede Spur.\nUnd sie sitzt still an ihrem Platz, das Licht scheint fahl und kalt,\nsie dürfte ahnen, was man redet – ihre Hände werden alt.\n\n[Chorus]\nSie soll es gewusst haben – sagt man, sagt man so,\ner will von nichts gewusst haben – irgendwo, irgendwie, irgendwo.\nEs muss doch jemand wissen, es dürfte längst bekannt sein –\ndoch ein Gerücht ist schneller als die Wahrheit, und die Wahrheit bleibt allein.\n\n[Bridge]\nIch frage sie am Abend, als der Flur schon leer ist:\n„Stimmt es, was man sagt?“ – Sie lächelt, wie ein Riss.\n„Ich muss es übersehen haben. Oder man hat es mir verschwiegen.\nDie Wahrheit, weißt du, lässt sich nicht so leicht verbiegen.“\n\n[Chorus]\nSie soll es gewusst haben – sagt man, sagt man so,\ner will von nichts gewusst haben – irgendwo, irgendwie, irgendwo.\nEs muss doch jemand wissen, es dürfte längst bekannt sein –\ndoch ein Gerücht ist schneller als die Wahrheit, und die Wahrheit bleibt allein.", "vocab": [["das Gerücht, die Gerüchte", "Information, die weitererzählt wird, aber nicht sicher stimmt"], ["flüstern", "sehr leise sprechen"], ["Zahlen schönen", "Zahlen so verändern, dass sie besser aussehen"], ["sie soll es gewusst haben", "andere behaupten, dass sie es wusste"], ["er will nichts gewusst haben", "er selbst behauptet, dass er nichts wusste"], ["es dürfte bekannt sein", "es ist wahrscheinlich bekannt (Vermutung)"], ["bemerken", "wahrnehmen, sehen"], ["die Akte, die Akten", "Sammlung offizieller Dokumente zu einem Fall"], ["fahl", "blass, ohne Farbe"], ["ahnen", "etwas vermuten, ohne es sicher zu wissen"], ["verschweigen", "etwas absichtlich nicht sagen"], ["verbiegen", "in eine falsche Form bringen; hier: verfälschen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["halb geflüstert, halb gelacht, wie ein bitterer ___:", "sie soll die Zahlen ___ haben – jeder weiß, es ist wahr.“", "doch ein ___ ist schneller als die Wahrheit, und die Wahrheit bleibt allein.", "die Akten können ___ sein, es fehlt von ihnen jede Spur.", "Ich muss es ___ haben. Oder man hat es mir verschwiegen."], "solutions": ["Duft", "geschönt", "Gerücht", "verschwunden", "übersehen"]}, "suno": "36eff134-6100-491b-9267-394a7dee9313"}, {"id": "c1-08-zwischen-gehen-und-bleiben", "level": "C1", "title": "Zwischen Gehen und Bleiben", "theme": "Lebensentscheidungen: Weggehen, Bleiben, Zugehörigkeit", "grammar": "Konzessive und adversative Konnektoren auf C1-Niveau (wenngleich, nichtsdestotrotz, wohingegen, zumal, ungeachtet + Genitiv)", "intro": "Ein Jobangebot in einer anderen Stadt, ein Leben, das man sich hier aufgebaut hat – und eine Entscheidung. Ein großer, filmischer Song über Gehen und Bleiben mit anspruchsvollen Konnektoren.", "lyrics": "[Verse 1]\nDer Brief liegt auf dem Tisch, das Angebot ist gut,\nwenngleich ein Teil von mir sich fürchtet vor dem Mut.\nDort wartet eine Zukunft, hell und unbekannt,\nwohingegen hier mein Leben Wurzeln in den Boden fand.\n\n[Chorus]\nZwischen Gehen und Bleiben steh ich in der Nacht,\nnichtsdestotrotz hab ich meine Koffer schon gepackt.\nZwischen Gehen und Bleiben, zwischen Hier und Dort –\nich trage meine Heimat in mir, an jeden Ort.\n\n[Verse 2]\nUngeachtet aller Zweifel ruft die Ferne meinen Namen,\nzumal die Kinder groß sind und ihre eigenen Wege nahmen.\nMeine Mutter sagt: „Geh nur“, wenngleich ihre Stimme bricht,\nund ich halte ihre Hände – loslassen kann ich nicht.\n\n[Chorus]\nZwischen Gehen und Bleiben steh ich in der Nacht,\nnichtsdestotrotz hab ich meine Koffer schon gepackt.\nZwischen Gehen und Bleiben, zwischen Hier und Dort –\nich trage meine Heimat in mir, an jeden Ort.\n\n[Bridge]\nVielleicht ist Gehen nur ein anderes Wort für Wachsen,\nvielleicht ist Bleiben nur ein anderes Wort für Treue.\nIch habe beides schon gelebt – und bin noch immer ganz.\nDer Morgen kommt. Ich steige ein. Ich nehme dich mit.\n\n[Chorus]\nZwischen Gehen und Bleiben steh ich in der Nacht,\nnichtsdestotrotz hab ich meine Koffer schon gepackt.\nZwischen Gehen und Bleiben, zwischen Hier und Dort –\nich trage meine Heimat in mir, an jeden Ort.", "vocab": [["das Angebot, die Angebote", "hier: eine Stelle, die man jemandem anbietet"], ["wenngleich", "obwohl (gehoben)"], ["wohingegen", "während (Gegensatz), im Unterschied dazu"], ["Wurzeln schlagen", "sich an einem Ort zu Hause fühlen"], ["nichtsdestotrotz", "trotzdem (gehoben)"], ["ungeachtet (+ Genitiv)", "trotz, ohne Rücksicht auf"], ["der Zweifel, die Zweifel", "Unsicherheit, ob etwas richtig ist"], ["die Ferne", "ein weit entfernter Ort"], ["zumal", "besonders weil, vor allem da"], ["loslassen", "nicht mehr festhalten"], ["die Treue", "Loyalität, man bleibt jemandem verbunden"], ["die Heimat", "Ort oder Gefühl, wo man sich zu Hause fühlt"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["___ ein Teil von mir sich fürchtet vor dem Mut.", "___ hier mein Leben Wurzeln in den Boden fand.", "nichtsdestotrotz hab ich meine ___ schon gepackt.", "Ungeachtet aller ___ ruft die Ferne meinen Namen,", "___ die Kinder groß sind und ihre eigenen Wege nahmen."], "solutions": ["wenngleich", "wohingegen", "Koffer", "Zweifel", "zumal"]}, "suno": "88b843f0-f9c8-4708-87fd-b06d7c93a228"}, {"id": "c1-09-nicht-zum-verkauf", "level": "C1", "title": "Die Stadt steht nicht zum Verkauf", "theme": "Wohnungsnot und Gentrifizierung: Mieterhöhung, Verdrängung, Nachbarschaft und Widerstand", "grammar": "Funktionsverbgefüge (zum Verkauf stehen, in Kauf nehmen, unter Druck setzen, zur Sprache bringen, in Frage stellen, Widerspruch einlegen, in Anspruch nehmen, eine Entscheidung treffen)", "intro": "Neue Fassaden, leere Fenster, steigende Mieten – dieser Song erzählt von einer Nachbarschaft, die sich gegen Verdrängung wehrt. Du übst dabei Funktionsverbgefüge wie unter Druck setzen, in Kauf nehmen und zur Sprache bringen.", "lyrics": "[Verse 1]\nIm Regen glänzt ein Bauschild: „Exklusives Wohnen am Kanal“,\nwo früher Frau Yilmaz ihren Kiosk hatte, ist es jetzt steril und kahl.\nDie Laternen fallen auf Fassaden, frisch gestrichen, kühl und weiß –\nund in jedem dritten Fenster brennt kein Licht, nur ein Preis.\n\n[Chorus]\nDie Stadt steht nicht zum Verkauf,\nwir nehmen es nicht in Kauf,\ndass man uns unter Druck setzt, Straße für Straße, Haus für Haus.\nWir bringen es zur Sprache, laut und klar:\nWir bleiben, denn wir sind schon da.\n\n[Verse 2]\nDann kam der Brief: „Modernisierung“, vierzig Prozent mehr Miete ab Januar,\nmeine Nachbarin, achtzig, stellt alles in Frage, was ihr einmal sicher war.\nWir legen Widerspruch ein, nehmen Beratung in Anspruch, treffen uns im Flur –\ndenn wer sein Zuhause verliert, verliert nicht nur vier Wände und eine Tür.\n\n[Chorus]\nDie Stadt steht nicht zum Verkauf,\nwir nehmen es nicht in Kauf,\ndass man uns unter Druck setzt, Straße für Straße, Haus für Haus.\nWir bringen es zur Sprache, laut und klar:\nWir bleiben, denn wir sind schon da.\n\n[Bridge]\nUm Mitternacht wird die Stadt zum Schaufenster,\ndie leeren Wohnungen starren dunkel wie Gespenster.\nDoch wir haben eine Entscheidung getroffen, leise, ohne Applaus:\nWir ziehen nicht aus.\n\n[Chorus]\nDie Stadt steht nicht zum Verkauf,\nwir nehmen es nicht in Kauf,\ndass man uns unter Druck setzt, Straße für Straße, Haus für Haus.\nWir bringen es zur Sprache, laut und klar:\nWir bleiben, denn wir sind schon da.\n\n[Outro]\nDie Stadt steht nicht zum Verkauf –\nwir ziehen nicht aus.", "vocab": [["das Bauschild, die Bauschilder", "Schild an einer Baustelle, das zeigt, was gebaut wird"], ["steril", "hier: sauber, aber ohne Leben und Gefühl"], ["die Fassade, die Fassaden", "die Außenseite eines Hauses, die man von der Straße sieht"], ["die Modernisierung, die Modernisierungen", "Umbau, der eine Wohnung moderner macht – und oft teurer"], ["zum Verkauf stehen", "verkauft werden sollen; man kann es kaufen"], ["unter Druck setzen", "jemanden stark drängen, etwas zu tun"], ["Widerspruch einlegen", "offiziell sagen, dass man mit einer Entscheidung nicht einverstanden ist"], ["in Anspruch nehmen", "ein Angebot oder eine Hilfe nutzen"], ["die Beratung, die Beratungen", "Hilfe durch Fachleute, z. B. beim Mieterverein"], ["das Gespenst, die Gespenster", "Geist, der (in Geschichten) nachts erscheint"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["wo früher Frau Yilmaz ihren ___ hatte, ist es jetzt steril und kahl.", "dass man uns unter ___ setzt, Straße für Straße, Haus für Haus.", "meine Nachbarin, achtzig, stellt alles in ___, was ihr einmal sicher war.", "Wir legen ___ ein, nehmen Beratung in Anspruch, treffen uns im Flur –", "Die Stadt steht nicht zum ___,"], "solutions": ["Kiosk", "Druck", "Frage", "Widerspruch", "Verkauf"]}, "suno": "3c2d53fc-6316-4049-9173-834d433150a6"}, {"id": "c1-10-sollte-das-display-leuchten", "level": "C1", "title": "Sollte das Display leuchten", "theme": "Ständige Erreichbarkeit: Homeoffice, Feierabend und das Recht auf Abschalten", "grammar": "Konditionalsätze ohne wenn (Verberststellung: Sollte …, Hätte …, Gäbe es …, Ist es …) sowie es sei denn und vorausgesetzt(, dass)", "intro": "Eine Nachricht um Mitternacht – und schon ist das Büro wieder im Schlafzimmer. Mit diesem Song übst du Konditionalsätze ohne wenn („Sollte das Display leuchten, …“) sowie es sei denn und vorausgesetzt.", "lyrics": "[Verse 1]\nKurz nach elf, die Straße glänzt wie schwarzer Lack im Regen,\nim Haus gegenüber leuchten Laptops, keiner kann sie weglegen.\nHätte ich mein Handy ausgeschaltet, wäre diese Nacht noch meine –\ndoch da steht: „Nur eine kurze Frage …“, und ich bin nicht mehr alleine.\n\n[Chorus]\nSollte das Display leuchten, lass es leuchten,\nsollte jemand schreiben, lass ihn warten bis um neun.\nIst es wirklich dringend, ist es morgen auch noch dringend –\nsollte die Nacht dich rufen, sag ihr nicht Nein.\n\n[Verse 2]\nDie Chefin schreibt um Mitternacht, drei Ausrufezeichen, kein Gruß.\nAntworte ich heute sofort, wird es morgen schon zum Muss.\nGäbe es ein Recht auf Feierabend, das auch wirklich gilt,\nwäre diese Stadt bei Nacht kein Großraumbüro, sondern ein Bild.\n\n[Chorus]\nSollte das Display leuchten, lass es leuchten,\nsollte jemand schreiben, lass ihn warten bis um neun.\nIst es wirklich dringend, ist es morgen auch noch dringend –\nsollte die Nacht dich rufen, sag ihr nicht Nein.\n\n[Bridge]\nIch bin erreichbar – es sei denn, es ist Nacht,\nich bin für alle da – vorausgesetzt, ich habe auch an mich gedacht.\nBrennt es wirklich, ruf mich an – doch nicht für jeden Satz,\nheute Nacht hat nur der Regen an meinem Fenster Platz.\n\n[Chorus]\nSollte das Display leuchten, lass es leuchten,\nsollte jemand schreiben, lass ihn warten bis um neun.\nIst es wirklich dringend, ist es morgen auch noch dringend –\nsollte die Nacht dich rufen, sag ihr nicht Nein.\n\n[Outro]\nSollte das Display leuchten –\nlass es leuchten.\nDie Nacht gehört uns.", "vocab": [["weglegen", "etwas zur Seite legen und nicht mehr benutzen"], ["das Display, die Displays", "der Bildschirm eines Handys oder Geräts"], ["dringend", "sehr eilig; muss schnell erledigt werden"], ["das Ausrufezeichen, die Ausrufezeichen", "das Satzzeichen „!“"], ["zum Muss werden", "zu etwas werden, das man unbedingt tun muss"], ["der Feierabend, die Feierabende", "die freie Zeit nach der Arbeit"], ["gelten", "gültig sein, wirklich wirksam sein"], ["das Großraumbüro, die Großraumbüros", "großes Büro, in dem viele Menschen zusammen arbeiten"], ["erreichbar", "so, dass man jemanden per Telefon oder Mail kontaktieren kann"], ["es sei denn", "außer wenn"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Hätte ich mein Handy ___, wäre diese Nacht noch meine –", "___ jemand schreiben, lass ihn warten bis um neun.", "Antworte ich heute sofort, wird es morgen schon zum ___.", "___ es ein Recht auf Feierabend, das auch wirklich gilt,", "Ich bin erreichbar – es sei ___, es ist Nacht,"], "solutions": ["ausgeschaltet", "sollte", "Muss", "Gäbe", "denn"]}, "suno": "14a91a45-5cde-4388-a464-8434d965da28"}];
